1	'use client';
2	
3	import 'react-pdf/dist/Page/TextLayer.css';
4	import 'react-pdf/dist/Page/AnnotationLayer.css';
5	import {
6	  ChevronLeft,
7	  ChevronRight,
8	  Download,
9	  Loader,
10	  Maximize2,
11	  Minimize2,
12	  RotateCw,
13	  XCircle,
14	  ZoomIn,
15	  ZoomOut,
16	} from 'lucide-react';
17	import { useCallback, useEffect, useRef, useState } from 'react';
18	import { Button } from '@/components/ui/button';
19	import { Input } from '@/components/ui/input';
20	import { usePdfViewer } from '@/hooks/usePdfViewer';
21	import {
22	  downloadBlob,
23	  fetchDocumentBlob,
24	  resolveDocumentDownloadUrl,
25	  resolvePdfDocumentSource,
26	  type PdfDocumentSource,
27	} from '@/functions/download/download-blob';
28	import { ensureFileNameExtension } from '@/functions/download/ensure-file-extension';
29	import { getUserFacingApiMessage } from '@/functions/analytics/axiosErrorProps';
30	import { sendToastMessage } from '@/functions/messages/toastMessage';
31	import { cn } from '@/lib/utils';
32	
33	export interface PdfDocumentViewerProps {
34	  /** When false, unloads source and ignores keyboard shortcuts. */
35	  active: boolean;
36	  fileUrl: string;
37	  fileName?: string;
38	  className?: string;
39	  /** Hide download (e.g. public external room). Default true. */
40	  canDownload?: boolean;
41	  /** Protected download endpoint, distinct from the preview URL. */
42	  downloadUrl?: string;
43	  /**
44	   * Embedded: maximize calls this (e.g. open focus modal).
45	   * Modal: maximize toggles internal expanded layout via onExpandedChange.
46	   */
47	  variant?: 'modal' | 'embedded';
48	  expanded?: boolean;
49	  onExpandedChange?: (expanded: boolean) => void;
50	  onRequestFocus?: () => void;
51	  showKeyboardHints?: boolean;
52	}
53	
54	/**
55	 * Shared PDF reader (zoom, pages, rotate, download, shortcuts).
56	 * Used by PDFViewerModal (focus) and Sala de Documentos (embedded).
57	 */
58	export function PdfDocumentViewer({
59	  active,
60	  fileUrl,
61	  fileName,
62	  className,
63	  canDownload = true,
64	  downloadUrl,
65	  variant = 'modal',
66	  expanded = false,
67	  onExpandedChange,
68	  onRequestFocus,
69	  showKeyboardHints = true,
70	}: PdfDocumentViewerProps) {
71	  const [numPages, setNumPages] = useState<number | null>(null);
72	  const [currentPage, setCurrentPage] = useState(1);
73	  const [scale, setScale] = useState(1);
74	  const [rotation, setRotation] = useState(0);
75	  const [pdfFile, setPdfFile] = useState<PdfDocumentSource | null>(null);
76	  const [isLoadingFile, setIsLoadingFile] = useState(false);
77	  const [loadFileError, setLoadFileError] = useState<string | null>(null);
78	
79	  const viewerRef = useRef<HTMLDivElement>(null);
80	  const pageRef = useRef<HTMLDivElement>(null);
81	  const rootRef = useRef<HTMLDivElement>(null);
82	
83	  const { isLoaded, isLoading, error, Document, Page } = usePdfViewer();
84	
85	  useEffect(() => {
86	    if (!active || !fileUrl) {
87	      setPdfFile(null);
88	      setIsLoadingFile(false);
89	      setLoadFileError(null);
90	      setNumPages(null);
91	      setCurrentPage(1);
92	      setScale(1);
93	      setRotation(0);
94	      return;
95	    }
96	
97	    let cancelled = false;
98	    setIsLoadingFile(true);
99	    setLoadFileError(null);
100	    setPdfFile(null);
101	
102	    resolvePdfDocumentSource(fileUrl)
103	      .catch(async (firstErr: unknown) => {
104	        // Transient Nexo/proxy resets: one automatic retry before surfacing UI error.
105	        await new Promise((resolve) => setTimeout(resolve, 350));
106	        if (cancelled) throw firstErr;
107	        return resolvePdfDocumentSource(fileUrl);
108	      })
109	      .then((source) => {
110	        if (!cancelled) setPdfFile(source);
111	      })
112	      .catch((err: unknown) => {
113	        if (!cancelled) {
114	          setLoadFileError(
115	            err instanceof Error ? err.message : 'Não foi possível carregar o PDF.'
116	          );
117	        }
118	      })
119	      .finally(() => {
120	        if (!cancelled) setIsLoadingFile(false);
121	      });
122	
123	    return () => {
124	      cancelled = true;
125	    };
126	  }, [active, fileUrl]);
127	
128	  const handleZoomIn = useCallback(() => {
129	    setScale((prev) => {
130	      const newScale = Math.min(prev + 0.2, 3);
131	      setTimeout(() => {
132	        if (viewerRef.current && pageRef.current) {
133	          const container = viewerRef.current;
134	          const page = pageRef.current;
135	          const containerRect = container.getBoundingClientRect();
136	          const pageRect = page.getBoundingClientRect();
137	          container.scrollTo({
138	            left: (pageRect.width - containerRect.width) / 2,
139	            top: Math.max(0, (pageRect.height - containerRect.height) / 2),
140	            behavior: 'smooth',
141	          });
142	        }
143	      }, 50);
144	      return newScale;
145	    });
146	  }, []);
147	
148	  const handleZoomOut = useCallback(() => {
149	    setScale((prev) => {
150	      const newScale = Math.max(prev - 0.2, 0.3);
151	      setTimeout(() => {
152	        if (viewerRef.current && pageRef.current) {
153	          const container = viewerRef.current;
154	          const page = pageRef.current;
155	          const containerRect = container.getBoundingClientRect();
156	          const pageRect = page.getBoundingClientRect();
157	          if (pageRect.width <= containerRect.width) container.scrollLeft = 0;
158	          if (pageRect.height <= containerRect.height) container.scrollTop = 0;
159	        }
160	      }, 50);
161	      return newScale;
162	    });
163	  }, []);
164	
165	  const handleRotate = useCallback(() => {
166	    setRotation((prev) => (prev + 90) % 360);
167	  }, []);
168	
169	  const handleFitToWidth = useCallback(() => {
170	    setTimeout(() => {
171	      if (viewerRef.current && pageRef.current) {
172	        const containerWidth = viewerRef.current.clientWidth - 40;
173	        const pageElement = pageRef.current.querySelector('.react-pdf__Page__canvas');
174	        if (pageElement) {
175	          const pageWidth = (pageElement as HTMLElement).offsetWidth;
176	          if (pageWidth > 0) {
177	            setScale((prev) => {
178	              const newScale = (containerWidth / pageWidth) * prev;
179	              return Math.max(0.3, Math.min(3, newScale));
180	            });
181	          }
182	        }
183	      }
184	    }, 100);
185	  }, []);
186	
187	  const handleActualSize = useCallback(() => {
188	    setScale(1);
189	  }, []);
190	
191	  const handleDownload = useCallback(async () => {
192	    if (!canDownload) return;
193	    const downloadName = ensureFileNameExtension(fileName || 'documento', 'application/pdf');
194	    try {
195	      if (downloadUrl) {
196	        const blob = await fetchDocumentBlob(resolveDocumentDownloadUrl(downloadUrl, fileUrl));
197	        downloadBlob(blob, downloadName);
198	        return;
199	      }
200	      if (pdfFile instanceof Blob) {
201	        downloadBlob(pdfFile, downloadName);
202	        return;
203	      }
204	      if (pdfFile && 'url' in pdfFile) {
205	        const blob = await fetchDocumentBlob(pdfFile.url);
206	        downloadBlob(blob, downloadName);
207	        return;
208	      }
209	      if (fileUrl) {
210	        const blob = await fetchDocumentBlob(fileUrl);
211	        downloadBlob(blob, downloadName);
212	      }
213	    } catch (err) {
214	      sendToastMessage({
215	        type: 'error',
216	        title: getUserFacingApiMessage(err, 'Não foi possível baixar o PDF.'),
217	      });
218	    }
219	  }, [canDownload, downloadUrl, pdfFile, fileUrl, fileName]);
220	
221	  const toggleFullscreen = useCallback(() => {
222	    if (variant === 'embedded') {
223	      onRequestFocus?.();
224	      return;
225	    }
226	    onExpandedChange?.(!expanded);
227	  }, [variant, onRequestFocus, onExpandedChange, expanded]);
228	
229	  const handlePrevPage = useCallback(() => {
230	    setCurrentPage((prev) => Math.max(prev - 1, 1));
231	  }, []);
232	
233	  const handleNextPage = useCallback(() => {
234	    setCurrentPage((prev) => Math.min(prev + 1, numPages || 1));
235	  }, [numPages]);
236	
237	  const goToPage = useCallback(
238	    (page: number) => {
239	      if (page >= 1 && page <= (numPages || 1)) setCurrentPage(page);
240	    },
241	    [numPages]
242	  );
243	
244	  const onDocumentLoadSuccess = useCallback(({ numPages: pages }: { numPages: number }) => {
245	    setNumPages(pages);
246	    setCurrentPage(1);
247	  }, []);
248	
249	  const onDocumentLoadError = useCallback((err: Error) => {
250	    if (process.env.NODE_ENV === 'development') {
251	      console.error('[PdfDocumentViewer] Failed to render PDF:', err.message);
252	    }
253	  }, []);
254	
255	  const handleKeyDown = useCallback(
256	    (e: KeyboardEvent) => {
257	      if (!active) return;
258	      // Embedded: only when focus is inside the viewer root
259	      if (variant === 'embedded' && rootRef.current && !rootRef.current.contains(document.activeElement)) {
260	        // Still allow when the viewer is hovered/clicked — attach listener only while active
261	        // Use a softer rule: if embedded, require pointer over root OR focus within
262	        const over = rootRef.current.matches(':hover');
263	        const focused = rootRef.current.contains(document.activeElement);
264	        if (!over && !focused) return;
265	      }
266	
267	      switch (e.key) {
268	        case 'ArrowLeft':
269	          e.preventDefault();
270	          handlePrevPage();
271	          break;
272	        case 'ArrowRight':
273	          e.preventDefault();
274	          handleNextPage();
275	          break;
276	        case '+':
277	        case '=':
278	          e.preventDefault();
279	          handleZoomIn();
280	          break;
281	        case '-':
282	          e.preventDefault();
283	          handleZoomOut();
284	          break;
285	        case '0':
286	          if (e.ctrlKey) {
287	            e.preventDefault();
288	            handleActualSize();
289	          }
290	          break;
291	        case 'r':
292	          if (e.ctrlKey) {
293	            e.preventDefault();
294	            handleRotate();
295	          }
296	          break;
297	      }
298	    },
299	    [
300	      active,
301	      variant,
302	      handlePrevPage,
303	      handleNextPage,
304	      handleZoomIn,
305	      handleZoomOut,
306	      handleActualSize,
307	      handleRotate,
308	    ]
309	  );
310	
311	  useEffect(() => {
312	    if (!active) return;
313	    document.addEventListener('keydown', handleKeyDown);
314	    return () => document.removeEventListener('keydown', handleKeyDown);
315	  }, [active, handleKeyDown]);
316	
317	  return (
318	    <div
319	      ref={rootRef}
320	      tabIndex={0}
321	      className={cn('flex min-h-0 flex-col outline-none', className)}
322	      data-testid="pdf-document-viewer"
323	    >
324	      {isLoading && (
325	        <div className="flex flex-1 items-center justify-center">
326	          <div className="flex flex-col items-center gap-3 p-8">
327	            <Loader className="h-8 w-8 animate-spin text-blue-500" />
328	            <div className="text-center">
329	              <h3 className="text-lg font-semibold text-title">Carregando visualizador PDF</h3>
330	              <p className="text-sm text-paragraph">Preparando componente, aguarde um momento</p>
331	            </div>
332	          </div>
333	        </div>
334	      )}
335	
336	      {error && (
337	        <div className="flex flex-1 items-center justify-center p-8">
338	          <div className="flex flex-col items-center gap-3">
339	            <XCircle className="h-8 w-8 text-red-500" />
340	            <h3 className="text-lg font-semibold text-title">Erro ao carregar visualizador</h3>
341	            <p className="text-sm text-paragraph">{error}</p>
342	          </div>
343	        </div>
344	      )}
345	
346	      {loadFileError && !isLoading && !error && isLoaded && (
347	        <div className="flex flex-1 items-center justify-center p-8">
348	          <div className="flex flex-col items-center gap-3">
349	            <XCircle className="h-8 w-8 text-red-500" />
350	            <p className="text-sm text-paragraph">{loadFileError}</p>
351	          </div>
352	        </div>
353	      )}
354	
355	      {!isLoading && !error && !loadFileError && isLoaded && (
356	        <>
357	          {isLoadingFile || !pdfFile ? (
358	            <div className="flex flex-1 items-center justify-center">
359	              <div className="flex flex-col items-center gap-3">
360	                <Loader className="h-8 w-8 animate-spin text-blue-500" />
361	                <p className="text-sm text-paragraph">Carregando PDF...</p>
362	              </div>
363	            </div>
364	          ) : (
365	            <>
366	              <div className="flex flex-wrap items-center justify-between gap-2 border-b bg-gray-50 px-2 py-2 dark:border-gray-700 dark:bg-gray-900">
367	                <div className="flex flex-wrap items-center gap-2">
368	                  <Button
369	                    variant="outline"
370	                    size="sm"
371	                    onClick={handleZoomOut}
372	                    disabled={scale <= 0.3}
373	                    title="Diminuir zoom (tecla -)"
374	                  >
375	                    <ZoomOut className="h-4 w-4 text-title" />
376	                  </Button>
377	                  <span className="min-w-[60px] text-center text-sm font-medium text-gray-700 dark:text-gray-300">
378	                    {Math.round(scale * 100)}%
379	                  </span>
380	                  <Button
381	                    variant="outline"
382	                    size="sm"
383	                    onClick={handleZoomIn}
384	                    disabled={scale >= 3}
385	                    title="Aumentar zoom (tecla +)"
386	                  >
387	                    <ZoomIn className="h-4 w-4 text-title" />
388	                  </Button>
389	                  <Button
390	                    variant="outline"
391	                    size="sm"
392	                    onClick={handleActualSize}
393	                    title="Tamanho real (Ctrl+0)"
394	                  >
395	                    <span className="text-title">100%</span>
396	                  </Button>
397	                  <Button
398	                    variant="outline"
399	                    size="sm"
400	                    onClick={handleFitToWidth}
401	                    title="Ajustar à largura"
402	                  >
403	                    <span className="text-title">Ajustar</span>
404	                  </Button>
405	                  <Button
406	                    variant="outline"
407	                    size="sm"
408	                    onClick={handleRotate}
409	                    title="Rotacionar (Ctrl+R)"
410	                  >
411	                    <RotateCw className="h-4 w-4 text-title" />
412	                  </Button>
413	                </div>
414	
415	                <div className="flex items-center gap-2 text-sm font-medium text-gray-700 dark:text-gray-300">
416	                  <Button
417	                    variant="outline"
418	                    size="sm"
419	                    disabled={currentPage <= 1}
420	                    onClick={handlePrevPage}
421	                    title="Página anterior (seta esquerda)"
422	                  >
423	                    <ChevronLeft className="h-4 w-4 text-title" />
424	                  </Button>
425	                  <div className="flex items-center gap-2">
426	                    <Input
427	                      type="number"
428	                      min={1}
429	                      max={numPages || 1}
430	                      value={currentPage}
431	                      onChange={(e) => goToPage(parseInt(e.target.value, 10))}
432	                      className="w-15"
433	                    />
434	                    <span className="text-nowrap text-paragraph">de {numPages || '...'}</span>
435	                  </div>
436	                  <Button
437	                    variant="outline"
438	                    size="sm"
439	                    disabled={currentPage >= (numPages || 1)}
440	                    onClick={handleNextPage}
441	                    title="Próxima página (seta direita)"
442	                  >
443	                    <ChevronRight className="h-4 w-4 text-title" />
444	                  </Button>
445	                </div>
446	
447	                <div className="flex items-center gap-2">
448	                  {variant === 'modal' ? (
449	                    <Button
450	                      variant="outline"
451	                      size="sm"
452	                      onClick={toggleFullscreen}
453	                      title="Alternar tela cheia"
454	                    >
455	                      {expanded ? (
456	                        <Minimize2 className="h-4 w-4 text-title" />
457	                      ) : (
458	                        <Maximize2 className="h-4 w-4 text-title" />
459	                      )}
460	                    </Button>
461	                  ) : null}
462	                  {canDownload && variant === 'modal' ? (
463	                    <Button
464	                      variant="outline"
465	                      size="sm"
466	                      onClick={handleDownload}
467	                      title="Baixar PDF"
468	                    >
469	                      <Download className="h-4 w-4 text-title" />
470	                    </Button>
471	                  ) : null}
472	                </div>
473	              </div>
474	
475	              <div
476	                ref={viewerRef}
477	                className="min-h-0 flex-1 overflow-auto rounded-b-lg bg-gray-100 dark:bg-gray-900"
478	                style={{
479	                  backgroundImage: `
480	                    linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), 
481	                    linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), 
482	                    linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), 
483	                    linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)
484	                  `,
485	                  backgroundSize: '20px 20px',
486	                  backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px',
487	                }}
488	              >
489	                <div className="flex min-h-full min-w-full items-start justify-center p-4">
490	                  <Document
491	                    file={pdfFile}
492	                    onLoadSuccess={onDocumentLoadSuccess}
493	                    onLoadError={onDocumentLoadError}
494	                    loading={
495	                      <div className="flex w-full flex-col items-center gap-3 p-8">
496	                        <Loader className="h-8 w-8 animate-spin text-blue-500" />
497	                        <div className="text-center">
498	                          <h3 className="text-lg font-semibold text-title">Carregando PDF</h3>
499	                          <p className="text-sm text-paragraph">
500	                            Processando documento, aguarde um momento
501	                          </p>
502	                        </div>
503	                      </div>
504	                    }
505	                    error={
506	                      <div className="flex flex-col items-center gap-3 rounded-lg bg-white p-8 shadow-lg dark:bg-gray-800">
507	                        <XCircle className="h-8 w-8 text-red-500" />
508	                        <h3 className="text-lg font-semibold text-title">Erro ao carregar PDF</h3>
509	                        <p className="text-sm text-paragraph">Ocorreu um erro inesperado</p>
510	                      </div>
511	                    }
512	                  >
513	                    <div
514	                      ref={pageRef}
515	                      style={{
516	                        transform: `rotate(${rotation}deg)`,
517	                        transition: 'transform 0.3s ease',
518	                      }}
519	                    >
520	                      <Page
521	                        pageNumber={currentPage}
522	                        scale={scale}
523	                        className="rounded-lg border border-gray-200 bg-white shadow-lg"
524	                        renderTextLayer
525	                        renderAnnotationLayer
526	                      />
527	                    </div>
528	                  </Document>
529	                </div>
530	              </div>
531	
532	              {showKeyboardHints && numPages ? (
