'use client';

import 'react-pdf/dist/Page/TextLayer.css';
import 'react-pdf/dist/Page/AnnotationLayer.css';
import {
  ChevronLeft,
  ChevronRight,
  Download,
  Loader,
  Maximize2,
  Minimize2,
  RotateCw,
  XCircle,
  ZoomIn,
  ZoomOut,
} from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { usePdfViewer } from '@/hooks/usePdfViewer';
import {
  downloadBlob,
  fetchDocumentBlob,
  resolveDocumentDownloadUrl,
  resolvePdfDocumentSource,
  type PdfDocumentSource,
} from '@/functions/download/download-blob';
import { ensureFileNameExtension } from '@/functions/download/ensure-file-extension';
import { getUserFacingApiMessage } from '@/functions/analytics/axiosErrorProps';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { cn } from '@/lib/utils';

export interface PdfDocumentViewerProps {
  /** When false, unloads source and ignores keyboard shortcuts. */
  active: boolean;
  fileUrl: string;
  fileName?: string;
  className?: string;
  /** Hide download (e.g. public external room). Default true. */
  canDownload?: boolean;
  /** Protected download endpoint, distinct from the preview URL. */
  downloadUrl?: string;
  /**
   * Embedded: maximize calls this (e.g. open focus modal).
   * Modal: maximize toggles internal expanded layout via onExpandedChange.
   */
  variant?: 'modal' | 'embedded';
  expanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  onRequestFocus?: () => void;
  showKeyboardHints?: boolean;
}

/**
 * Shared PDF reader (zoom, pages, rotate, download, shortcuts).
 * Used by PDFViewerModal (focus) and Sala de Documentos (embedded).
 */
export function PdfDocumentViewer({
  active,
  fileUrl,
  fileName,
  className,
  canDownload = true,
  downloadUrl,
  variant = 'modal',
  expanded = false,
  onExpandedChange,
  onRequestFocus,
  showKeyboardHints = true,
}: PdfDocumentViewerProps) {
  const [numPages, setNumPages] = useState<number | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [scale, setScale] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [pdfFile, setPdfFile] = useState<PdfDocumentSource | null>(null);
  const [isLoadingFile, setIsLoadingFile] = useState(false);
  const [loadFileError, setLoadFileError] = useState<string | null>(null);

  const viewerRef = useRef<HTMLDivElement>(null);
  const pageRef = useRef<HTMLDivElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  const { isLoaded, isLoading, error, Document, Page } = usePdfViewer();

  useEffect(() => {
    if (!active || !fileUrl) {
      setPdfFile(null);
      setIsLoadingFile(false);
      setLoadFileError(null);
      setNumPages(null);
      setCurrentPage(1);
      setScale(1);
      setRotation(0);
      return;
    }

    let cancelled = false;
    setIsLoadingFile(true);
    setLoadFileError(null);
    setPdfFile(null);

    resolvePdfDocumentSource(fileUrl)
      .catch(async (firstErr: unknown) => {
        // Transient Nexo/proxy resets: one automatic retry before surfacing UI error.
        await new Promise((resolve) => setTimeout(resolve, 350));
        if (cancelled) throw firstErr;
        return resolvePdfDocumentSource(fileUrl);
      })
      .then((source) => {
        if (!cancelled) setPdfFile(source);
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setLoadFileError(
            err instanceof Error ? err.message : 'Não foi possível carregar o PDF.'
          );
        }
      })
      .finally(() => {
        if (!cancelled) setIsLoadingFile(false);
      });

    return () => {
      cancelled = true;
    };
  }, [active, fileUrl]);

  const handleZoomIn = useCallback(() => {
    setScale((prev) => {
      const newScale = Math.min(prev + 0.2, 3);
      setTimeout(() => {
        if (viewerRef.current && pageRef.current) {
          const container = viewerRef.current;
          const page = pageRef.current;
          const containerRect = container.getBoundingClientRect();
          const pageRect = page.getBoundingClientRect();
          container.scrollTo({
            left: (pageRect.width - containerRect.width) / 2,
            top: Math.max(0, (pageRect.height - containerRect.height) / 2),
            behavior: 'smooth',
          });
        }
      }, 50);
      return newScale;
    });
  }, []);

  const handleZoomOut = useCallback(() => {
    setScale((prev) => {
      const newScale = Math.max(prev - 0.2, 0.3);
      setTimeout(() => {
        if (viewerRef.current && pageRef.current) {
          const container = viewerRef.current;
          const page = pageRef.current;
          const containerRect = container.getBoundingClientRect();
          const pageRect = page.getBoundingClientRect();
          if (pageRect.width <= containerRect.width) container.scrollLeft = 0;
          if (pageRect.height <= containerRect.height) container.scrollTop = 0;
        }
      }, 50);
      return newScale;
    });
  }, []);

  const handleRotate = useCallback(() => {
    setRotation((prev) => (prev + 90) % 360);
  }, []);

  const handleFitToWidth = useCallback(() => {
    setTimeout(() => {
      if (viewerRef.current && pageRef.current) {
        const containerWidth = viewerRef.current.clientWidth - 40;
        const pageElement = pageRef.current.querySelector('.react-pdf__Page__canvas');
        if (pageElement) {
          const pageWidth = (pageElement as HTMLElement).offsetWidth;
          if (pageWidth > 0) {
            setScale((prev) => {
              const newScale = (containerWidth / pageWidth) * prev;
              return Math.max(0.3, Math.min(3, newScale));
            });
          }
        }
      }
    }, 100);
  }, []);

  const handleActualSize = useCallback(() => {
    setScale(1);
  }, []);

  const handleDownload = useCallback(async () => {
    if (!canDownload) return;
    const downloadName = ensureFileNameExtension(fileName || 'documento', 'application/pdf');
    try {
      if (downloadUrl) {
        const blob = await fetchDocumentBlob(resolveDocumentDownloadUrl(downloadUrl, fileUrl));
        downloadBlob(blob, downloadName);
        return;
      }
      if (pdfFile instanceof Blob) {
        downloadBlob(pdfFile, downloadName);
        return;
      }
      if (pdfFile && 'url' in pdfFile) {
        const blob = await fetchDocumentBlob(pdfFile.url);
        downloadBlob(blob, downloadName);
        return;
      }
      if (fileUrl) {
        const blob = await fetchDocumentBlob(fileUrl);
        downloadBlob(blob, downloadName);
      }
    } catch (err) {
      sendToastMessage({
        type: 'error',
        title: getUserFacingApiMessage(err, 'Não foi possível baixar o PDF.'),
      });
    }
  }, [canDownload, downloadUrl, pdfFile, fileUrl, fileName]);

  const toggleFullscreen = useCallback(() => {
    if (variant === 'embedded') {
      onRequestFocus?.();
      return;
    }
    onExpandedChange?.(!expanded);
  }, [variant, onRequestFocus, onExpandedChange, expanded]);

  const handlePrevPage = useCallback(() => {
    setCurrentPage((prev) => Math.max(prev - 1, 1));
  }, []);

  const handleNextPage = useCallback(() => {
    setCurrentPage((prev) => Math.min(prev + 1, numPages || 1));
  }, [numPages]);

  const goToPage = useCallback(
    (page: number) => {
      if (page >= 1 && page <= (numPages || 1)) setCurrentPage(page);
    },
    [numPages]
  );

  const onDocumentLoadSuccess = useCallback(({ numPages: pages }: { numPages: number }) => {
    setNumPages(pages);
    setCurrentPage(1);
  }, []);

  const onDocumentLoadError = useCallback((err: Error) => {
    if (process.env.NODE_ENV === 'development') {
      console.error('[PdfDocumentViewer] Failed to render PDF:', err.message);
    }
  }, []);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (!active) return;
      // Embedded: only when focus is inside the viewer root
      if (variant === 'embedded' && rootRef.current && !rootRef.current.contains(document.activeElement)) {
        // Still allow when the viewer is hovered/clicked — attach listener only while active
        // Use a softer rule: if embedded, require pointer over root OR focus within
        const over = rootRef.current.matches(':hover');
        const focused = rootRef.current.contains(document.activeElement);
        if (!over && !focused) return;
      }

      switch (e.key) {
        case 'ArrowLeft':
          e.preventDefault();
          handlePrevPage();
          break;
        case 'ArrowRight':
          e.preventDefault();
          handleNextPage();
          break;
        case '+':
        case '=':
          e.preventDefault();
          handleZoomIn();
          break;
        case '-':
          e.preventDefault();
          handleZoomOut();
          break;
        case '0':
          if (e.ctrlKey) {
            e.preventDefault();
            handleActualSize();
          }
          break;
        case 'r':
          if (e.ctrlKey) {
            e.preventDefault();
            handleRotate();
          }
          break;
      }
    },
    [
      active,
      variant,
      handlePrevPage,
      handleNextPage,
      handleZoomIn,
      handleZoomOut,
      handleActualSize,
      handleRotate,
    ]
  );

  useEffect(() => {
    if (!active) return;
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [active, handleKeyDown]);

  return (
    <div
      ref={rootRef}
      tabIndex={0}
      className={cn('flex min-h-0 flex-col outline-none', className)}
      data-testid="pdf-document-viewer"
    >
      {isLoading && (
        <div className="flex flex-1 items-center justify-center">
          <div className="flex flex-col items-center gap-3 p-8">
            <Loader className="h-8 w-8 animate-spin text-blue-500" />
            <div className="text-center">
              <h3 className="text-lg font-semibold text-title">Carregando visualizador PDF</h3>
              <p className="text-sm text-paragraph">Preparando componente, aguarde um momento</p>
            </div>
          </div>
        </div>
      )}

      {error && (
        <div className="flex flex-1 items-center justify-center p-8">
          <div className="flex flex-col items-center gap-3">
            <XCircle className="h-8 w-8 text-red-500" />
            <h3 className="text-lg font-semibold text-title">Erro ao carregar visualizador</h3>
            <p className="text-sm text-paragraph">{error}</p>
          </div>
        </div>
      )}

      {loadFileError && !isLoading && !error && isLoaded && (
        <div className="flex flex-1 items-center justify-center p-8">
          <div className="flex flex-col items-center gap-3">
            <XCircle className="h-8 w-8 text-red-500" />
            <p className="text-sm text-paragraph">{loadFileError}</p>
          </div>
        </div>
      )}

      {!isLoading && !error && !loadFileError && isLoaded && (
        <>
          {isLoadingFile || !pdfFile ? (
            <div className="flex flex-1 items-center justify-center">
              <div className="flex flex-col items-center gap-3">
                <Loader className="h-8 w-8 animate-spin text-blue-500" />
                <p className="text-sm text-paragraph">Carregando PDF...</p>
              </div>
            </div>
          ) : (
            <>
              <div className="flex flex-wrap items-center justify-between gap-2 border-b bg-gray-50 px-2 py-2 dark:border-gray-700 dark:bg-gray-900">
                <div className="flex flex-wrap items-center gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleZoomOut}
                    disabled={scale <= 0.3}
                    title="Diminuir zoom (tecla -)"
                  >
                    <ZoomOut className="h-4 w-4 text-title" />
                  </Button>
                  <span className="min-w-[60px] text-center text-sm font-medium text-gray-700 dark:text-gray-300">
                    {Math.round(scale * 100)}%
                  </span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleZoomIn}
                    disabled={scale >= 3}
                    title="Aumentar zoom (tecla +)"
                  >
                    <ZoomIn className="h-4 w-4 text-title" />
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleActualSize}
                    title="Tamanho real (Ctrl+0)"
                  >
                    <span className="text-title">100%</span>
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleFitToWidth}
                    title="Ajustar à largura"
                  >
                    <span className="text-title">Ajustar</span>
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleRotate}
                    title="Rotacionar (Ctrl+R)"
                  >
                    <RotateCw className="h-4 w-4 text-title" />
                  </Button>
                </div>

                <div className="flex items-center gap-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={currentPage <= 1}
                    onClick={handlePrevPage}
                    title="Página anterior (seta esquerda)"
                  >
                    <ChevronLeft className="h-4 w-4 text-title" />
                  </Button>
                  <div className="flex items-center gap-2">
                    <Input
                      type="number"
                      min={1}
                      max={numPages || 1}
                      value={currentPage}
                      onChange={(e) => goToPage(parseInt(e.target.value, 10))}
                      className="w-15"
                    />
                    <span className="text-nowrap text-paragraph">de {numPages || '...'}</span>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={currentPage >= (numPages || 1)}
                    onClick={handleNextPage}
                    title="Próxima página (seta direita)"
                  >
                    <ChevronRight className="h-4 w-4 text-title" />
                  </Button>
                </div>

                <div className="flex items-center gap-2">
                  {variant === 'modal' ? (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={toggleFullscreen}
                      title="Alternar tela cheia"
                    >
                      {expanded ? (
                        <Minimize2 className="h-4 w-4 text-title" />
                      ) : (
                        <Maximize2 className="h-4 w-4 text-title" />
                      )}
                    </Button>
                  ) : null}
                  {canDownload && variant === 'modal' ? (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleDownload}
                      title="Baixar PDF"
                    >
                      <Download className="h-4 w-4 text-title" />
                    </Button>
                  ) : null}
                </div>
              </div>

              <div
                ref={viewerRef}
                className="min-h-0 flex-1 overflow-auto rounded-b-lg bg-gray-100 dark:bg-gray-900"
                style={{
                  backgroundImage: `
                    linear-gradient(45deg, rgba(0,0,0,0.05) 25%, transparent 25%), 
                    linear-gradient(-45deg, rgba(0,0,0,0.05) 25%, transparent 25%), 
                    linear-gradient(45deg, transparent 75%, rgba(0,0,0,0.05) 75%), 
                    linear-gradient(-45deg, transparent 75%, rgba(0,0,0,0.05) 75%)
                  `,
                  backgroundSize: '20px 20px',
                  backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px',
                }}
              >
                <div className="flex min-h-full min-w-full items-start justify-center p-4">
                  <Document
                    file={pdfFile}
                    onLoadSuccess={onDocumentLoadSuccess}
                    onLoadError={onDocumentLoadError}
                    loading={
                      <div className="flex w-full flex-col items-center gap-3 p-8">
                        <Loader className="h-8 w-8 animate-spin text-blue-500" />
                        <div className="text-center">
                          <h3 className="text-lg font-semibold text-title">Carregando PDF</h3>
                          <p className="text-sm text-paragraph">
                            Processando documento, aguarde um momento
                          </p>
                        </div>
                      </div>
                    }
                    error={
                      <div className="flex flex-col items-center gap-3 rounded-lg bg-white p-8 shadow-lg dark:bg-gray-800">
                        <XCircle className="h-8 w-8 text-red-500" />
                        <h3 className="text-lg font-semibold text-title">Erro ao carregar PDF</h3>
                        <p className="text-sm text-paragraph">Ocorreu um erro inesperado</p>
                      </div>
                    }
                  >
                    <div
                      ref={pageRef}
                      style={{
                        transform: `rotate(${rotation}deg)`,
                        transition: 'transform 0.3s ease',
                      }}
                    >
                      <Page
                        pageNumber={currentPage}
                        scale={scale}
                        className="rounded-lg border border-gray-200 bg-white shadow-lg"
                        renderTextLayer
                        renderAnnotationLayer
                      />
                    </div>
                  </Document>
                </div>
              </div>

              {showKeyboardHints && numPages ? (
                <div className="flex items-center justify-between px-2 py-1.5 text-xs text-paragraph">
                  <span>Use as setas do teclado para navegar</span>
                  <span>Zoom: Ctrl + (+/-) | Rotação: Ctrl + R</span>
                </div>
              ) : null}
            </>
          )}
        </>
      )}
    </div>
  );
