'use client';

import { usePdfViewer } from '@/hooks/usePdfViewer';
import { directApi, getTokenViaAPI, localApi } from '@/utils/api';
import { FileX, Loader } from 'lucide-react';
import Image from 'next/image';
import { useEffect, useMemo, useState } from 'react';
import {
    isAppProxiedPreviewUrl,
    resolveDocumentPreviewFetchUrl,
} from './resolveDocumentPreviewFetchUrl';

const DEFAULT_PREVIEW_PAGE_WIDTH = 80;

interface IPdfConfig {
    url: string;
    httpHeaders?: Record<string, string>;
}

export interface IDocumentPreviewerProps {
    url: string;
    documentType: string;
    pageWidth?: number;
    /**
     * PK de `Documento` da **esteira** apenas.
     * Usado para rebuild de URL GCS expirada → `/api/v2/documentos/{id}/download/`.
     * Não passar PK de satélite Due (certidão, análise, R/V LOA, etc.).
     */
    documentId?: string | number | null;
}

export function DocumentPreviewer({
    url,
    documentType,
    pageWidth = DEFAULT_PREVIEW_PAGE_WIDTH,
    documentId,
}: IDocumentPreviewerProps) {
    const { isLoaded, isLoading, error, Document, Page } = usePdfViewer();
    const [pdfConfig, setPdfConfig] = useState<IPdfConfig | null>(null);
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [fetchLoading, setFetchLoading] = useState(true);
    const [fetchError, setFetchError] = useState(false);

    const previewUrl = useMemo(
        () => resolveDocumentPreviewFetchUrl(url, documentId),
        [documentId, url],
    );

    useEffect(() => {
        if (!previewUrl || !documentType) return;

        let isActive = true;
        let imageObjectUrl: string | null = null;

        async function loadPreview() {
            setFetchLoading(true);
            setFetchError(false);
            setPdfConfig(null);
            setImageSrc(null);

            try {
                if (documentType === 'pdf') {
                    const token = await getTokenViaAPI();
                    if (!isActive) return;

                    setPdfConfig({
                        url: previewUrl,
                        ...(token ? { httpHeaders: { Authorization: `Bearer ${token}` } } : {}),
                    });
                    return;
                }

                const previewClient = isAppProxiedPreviewUrl(previewUrl) ? localApi : directApi;
                const { data: blob } = await previewClient.get<Blob>(previewUrl, {
                    responseType: 'blob',
                });
                imageObjectUrl = URL.createObjectURL(blob);
                if (!isActive) {
                    URL.revokeObjectURL(imageObjectUrl);
                    return;
                }

                setImageSrc(imageObjectUrl);
            } catch {
                if (isActive) setFetchError(true);
            } finally {
                if (isActive) setFetchLoading(false);
            }
        }

        loadPreview();

        return () => {
            isActive = false;
            if (imageObjectUrl) URL.revokeObjectURL(imageObjectUrl);
        };
    }, [documentType, previewUrl]);

    if (isLoading || fetchLoading) {
        return (
            <>
                <Loader className="animate-spin" />
                <p className="mt-1 text-center text-sm text-paragraph">
                    Carregando pré visualização
                </p>
            </>
        );
    }

    if (error || fetchError || !isLoaded) {
        return (
            <>
                <FileX size={30} className="mr-4 text-gray-300 dark:text-slate-500" />
                <p className="mt-1 text-center text-sm text-paragraph">
                    Erro ao carregar pré visualização
                </p>
            </>
        );
    }

    if (documentType === 'pdf' && pdfConfig && Document && Page) {
        return (
            <Document file={pdfConfig} loading={<Loader className="animate-spin" />}>
                <Page
                    pageNumber={1}
                    width={pageWidth}
                    renderTextLayer={false}
                    renderAnnotationLayer={false}
                />
            </Document>
        );
    }

    return (
        <Image
            src={imageSrc ?? ''}
            alt="Documento"
            width={pageWidth}
            height={pageWidth}
            className="size-full object-cover opacity-60"
        />
    );
}

