import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { render, screen, waitFor } from '@testing-library/react';
import type { ReactNode } from 'react';

jest.mock('@/hooks/usePdfViewer', () => ({
    usePdfViewer: jest.fn(),
}));
jest.mock('@/utils/api', () => ({
    directApi: {
        get: jest.fn(),
    },
    localApi: {
        get: jest.fn(),
    },
    getTokenViaAPI: jest.fn(),
}));
jest.mock('@/config/environment.config', () => ({
    getApiUrl: jest.fn(() => 'https://api.example.com'),
}));

const PdfDocument = jest.fn(({ children }: { children: ReactNode; file?: unknown }) => (
    <div data-testid="pdf-document">{children}</div>
));
const PdfPage = jest.fn(({ width }: { width: number }) => (
    <div data-testid="pdf-page" data-width={width} />
));
const createObjectURL = jest.fn<(blob: Blob) => string>(() => 'blob:document-preview');
const revokeObjectURL = jest.fn<(url: string) => void>();

const { usePdfViewer: mockedUsePdfViewer } = jest.requireMock<{
    usePdfViewer: jest.MockedFunction<
        typeof import('@/hooks/usePdfViewer').usePdfViewer
    >;
}>('@/hooks/usePdfViewer');
const {
    directApi: { get: mockedDirectApiGet },
    localApi: { get: mockedLocalApiGet },
    getTokenViaAPI: mockedGetTokenViaAPI,
} = jest.requireMock<{
    directApi: {
        get: jest.MockedFunction<typeof import('@/utils/api').directApi.get>;
    };
    localApi: {
        get: jest.MockedFunction<typeof import('@/utils/api').localApi.get>;
    };
    getTokenViaAPI: jest.MockedFunction<typeof import('@/utils/api').getTokenViaAPI>;
}>('@/utils/api');
const { DocumentPreviewer } =
    jest.requireActual<typeof import('../DocumentPreviewer')>('../DocumentPreviewer');

describe('DocumentPreviewer', () => {
    beforeEach(() => {
        Object.defineProperty(URL, 'createObjectURL', {
            configurable: true,
            value: createObjectURL,
        });
        Object.defineProperty(URL, 'revokeObjectURL', {
            configurable: true,
            value: revokeObjectURL,
        });

        mockedUsePdfViewer.mockReturnValue({
            isLoaded: true,
            isLoading: false,
            error: null,
            Document: PdfDocument,
            Page: PdfPage,
            pdfjs: null,
            initializePdf: jest.fn(),
        });
    });

    afterEach(() => {
        jest.clearAllMocks();
        mockedUsePdfViewer.mockReturnValue({
            isLoaded: true,
            isLoading: false,
            error: null,
            Document: PdfDocument,
            Page: PdfPage,
            pdfjs: null,
            initializePdf: jest.fn(),
        });
    });

    it('carrega PDF autenticado e usa a largura padrão', async () => {
        mockedGetTokenViaAPI.mockResolvedValue('token-preview');

        render(
            <DocumentPreviewer
                url="https://example.com/documento.pdf"
                documentType="pdf"
            />,
        );

        await waitFor(() => expect(screen.getByTestId('pdf-page')).toBeInTheDocument());

        expect(mockedGetTokenViaAPI).toHaveBeenCalledTimes(1);
        expect(PdfDocument.mock.calls[0]?.[0]).toEqual(
            expect.objectContaining({
                file: {
                    url: 'https://example.com/documento.pdf',
                    httpHeaders: { Authorization: 'Bearer token-preview' },
                },
            }),
        );
        expect(screen.getByTestId('pdf-page')).toHaveAttribute('data-width', '80');
    });

    it('converte url sem stream/download para endpoint de download da API', async () => {
        mockedGetTokenViaAPI.mockResolvedValue('token-preview');

        render(
            <DocumentPreviewer
                url="https://cdn.example.com/arquivo.pdf"
                documentType="pdf"
                documentId={590}
            />,
        );

        await waitFor(() => expect(screen.getByTestId('pdf-page')).toBeInTheDocument());

        expect(PdfDocument.mock.calls[0]?.[0]).toEqual(
            expect.objectContaining({
                file: {
                    url: 'https://api.example.com/api/v2/documentos/590/download/',
                    httpHeaders: { Authorization: 'Bearer token-preview' },
                },
            }),
        );
    });

    it('não converte url que já termina em /download/', async () => {
        mockedGetTokenViaAPI.mockResolvedValue(null);
        const downloadUrl = 'https://api.example.com/api/v2/documentos/590/download/';

        render(
            <DocumentPreviewer
                url={downloadUrl}
                documentType="pdf"
                documentId={999}
            />,
        );

        await waitFor(() => expect(screen.getByTestId('pdf-page')).toBeInTheDocument());

        expect(PdfDocument.mock.calls[0]?.[0]).toEqual(
            expect.objectContaining({
                file: {
                    url: downloadUrl,
                },
            }),
        );
    });

    it('aplica pageWidth customizado ao PDF', async () => {
        mockedGetTokenViaAPI.mockResolvedValue(null);

        render(
            <DocumentPreviewer
                url="https://example.com/documento.pdf"
                documentType="pdf"
                pageWidth={480}
            />,
        );

        await waitFor(() => expect(screen.getByTestId('pdf-page')).toBeInTheDocument());

        expect(screen.getByTestId('pdf-page')).toHaveAttribute('data-width', '480');
    });

    it('carrega imagem como blob e revoga a URL ao desmontar', async () => {
        const blob = new Blob(['image'], { type: 'image/png' });
        mockedDirectApiGet.mockResolvedValue({ data: blob } as never);

        const { unmount } = render(
            <DocumentPreviewer
                url="https://example.com/documento.png"
                documentType="img"
                pageWidth={320}
            />,
        );

        const image = await screen.findByRole('img', { name: 'Documento' });

        expect(mockedDirectApiGet).toHaveBeenCalledWith(
            'https://example.com/documento.png',
            { responseType: 'blob' },
        );
        expect(createObjectURL).toHaveBeenCalledWith(blob);
        expect(image).toHaveAttribute('src', 'blob:document-preview');
        expect(image).toHaveAttribute('width', '320');
        expect(image).toHaveAttribute('height', '320');

        unmount();

        expect(revokeObjectURL).toHaveBeenCalledWith('blob:document-preview');
    });

    it('preserva /api/file e busca a imagem via localApi mesmo com documentId', async () => {
        const blob = new Blob(['image'], { type: 'image/jpeg' });
        mockedLocalApiGet.mockResolvedValue({ data: blob } as never);
        const proxiedUrl =
            '/api/file?url=https%3A%2F%2Fcdn.example.com%2Fscan.jpg&fileName=scan.jpg';

        render(
            <DocumentPreviewer
                url={proxiedUrl}
                documentType="img"
                documentId={19}
            />,
        );

        const image = await screen.findByRole('img', { name: 'Documento' });

        expect(mockedLocalApiGet).toHaveBeenCalledWith(proxiedUrl, {
            responseType: 'blob',
        });
        expect(mockedDirectApiGet).not.toHaveBeenCalled();
        expect(image).toHaveAttribute('src', 'blob:document-preview');
    });

    it('mostra erro quando o documento não pode ser carregado', async () => {
        mockedDirectApiGet.mockRejectedValue(new Error('Falha de rede'));

        render(
            <DocumentPreviewer
                url="https://example.com/documento.png"
                documentType="img"
            />,
        );

        expect(
            await screen.findByText('Erro ao carregar pré visualização'),
        ).toBeInTheDocument();
    });
});

