68	function DocumentBentoPreview({ url, documentType }: { url: string; documentType: string }) {
69	    const previewRef = useRef<HTMLDivElement>(null);
70	    const { isLoaded, isLoading, error, Document, Page } = usePdfViewer();
71	    const [previewWidth, setPreviewWidth] = useState(160);
72	    const [pdfConfig, setPdfConfig] = useState<{
73	        url: string;
74	        httpHeaders?: Record<string, string>;
75	    } | null>(null);
76	    const [imageSrc, setImageSrc] = useState<string | null>(null);
77	    const [fetchLoading, setFetchLoading] = useState(true);
78	    const [fetchError, setFetchError] = useState(false);
79	
80	    useEffect(() => {
81	        const element = previewRef.current;
82	        if (!element) return;
83	
84	        const observer = new ResizeObserver(([entry]) => {
85	            setPreviewWidth(Math.max(100, Math.floor(entry.contentRect.width - 16)));
86	        });
87	
88	        observer.observe(element);
89	        return () => observer.disconnect();
90	    }, []);
91	
92	    useEffect(() => {
93	        if (!url || !documentType) return;
94	        setFetchLoading(true);
95	        setFetchError(false);
96	
97	        if (documentType === 'pdf') {
98	            getTokenViaAPI().then((token) => {
99	                setPdfConfig({
100	                    url,
101	                    ...(token ? { httpHeaders: { Authorization: `Bearer ${token}` } } : {}),
102	                });
103	                setFetchLoading(false);
104	            });
105	        } else {
106	            directApi
107	                .get(url, { responseType: 'blob' })
108	                .then(({ data: blob }) => {
109	                    setImageSrc(URL.createObjectURL(blob));
110	                    setFetchLoading(false);
111	                })
112	                .catch(() => {
113	                    setFetchError(true);
114	                    setFetchLoading(false);
115	                });
116	        }
117	    }, [url, documentType]);
118	
119	    const previewShell = (content: React.ReactNode) => (
120	        <div ref={previewRef} className={bentoDocCardPreviewInnerClass}>
121	            {content}
122	        </div>
123	    );
124	
125	    if (isLoading || fetchLoading) {
126	        return previewShell(
127	            <div className={bentoDocCardEmptyPreviewClass}>
128	                <Loader className="size-6 animate-spin" />
129	                <span className="text-xs">Carregando prévia…</span>
130	            </div>,
131	        );
132	    }
133	
134	    if (error || fetchError || !isLoaded) {
135	        return previewShell(
136	            <div className={bentoDocCardEmptyPreviewClass}>
137	                <FileX className="size-10 opacity-40" />
138	                <span className="text-xs">Prévia indisponível</span>
139	            </div>,
140	        );
141	    }
142	
143	    if (documentType === 'pdf' && pdfConfig && Document && Page) {
144	        return previewShell(
145	            <Document file={pdfConfig} loading={<Loader className="size-6 animate-spin" />}>
146	                <Page
147	                    pageNumber={1}
148	                    width={previewWidth}
149	                    renderTextLayer={false}
150	                    renderAnnotationLayer={false}
151	                />
152	            </Document>,
153	        );
154	    }
155	
156	    return previewShell(
157	        <Image
158	            src={imageSrc ?? ''}
159	            alt="Prévia do documento"
160	            width={previewWidth}
161	            height={Math.round(previewWidth * 1.35)}
162	            className="max-h-full max-w-full object-contain"
163	        />,
164	    );
165	}
