import { Documento, DocumentoAnalise } from '@/interfaces/IDocumento';
import {
  createDocumentoAnaliseFeedback,
  DocumentoAnaliseDetail,
  DocumentoAnaliseHistorico,
  DocumentoAnaliseFeedbackCategoria,
  DocumentoAnaliseFeedbackDecisao,
  getDocumentoAnaliseDetail,
  getDocumentoAnaliseFeedbacks,
  reAnalisarDocumento,
} from '@/services/comercial-documents';
import { useDocumentoWebSocket } from '@/hooks/useDocumentoWebSocket';
import { COLORS, withAlpha } from '@/app/crm/gerencial-broker/_constants/colors';
import { usePdfViewer } from '@/hooks/usePdfViewer';
import { directApi, getTokenViaAPI } from '@/utils/api';

interface AIAnalysisModalProps {
  isOpen: boolean;
  onClose: () => void;
  documento: Documento | null;
  analise: DocumentoAnalise | null;
  onApprove: (docId: number) => Promise<void>;
  onReject: (docId: number) => Promise<void>;
  onAnalysisComplete?: () => void;
  isProcessing?: boolean;
  documentUrl?: string | null;
  /** Quando false, oculta aprovar/rejeitar/re-analisar (ex.: revisão documental antes da Due). */
  showDocumentActions?: boolean;
  /** Quando false, oculta feedback de curadoria/auditoria IA (ex.: COMERCIAL_BROKER). */
  showAuditFeedback?: boolean;
}

const getRecommendationConfig = (recomendacao: string | null) => {
  switch (recomendacao) {
    case 'APROVADO':
      return {
        bgStyle: { backgroundColor: withAlpha(COLORS.green, 0.05), borderColor: withAlpha(COLORS.green, 0.2) },
        textStyle: { color: COLORS.green },
        barStyle: { backgroundColor: COLORS.green },
        icon: <CheckCircle className="w-6 h-6" style={{ color: COLORS.green }} />
      };
    case 'REPROVADO':
      return {
        bgStyle: { backgroundColor: withAlpha(COLORS.red, 0.05), borderColor: withAlpha(COLORS.red, 0.2) },
        textStyle: { color: COLORS.red },
        barStyle: { backgroundColor: COLORS.red },
        icon: <AlertCircle className="w-6 h-6" style={{ color: COLORS.red }} />
      };
    case 'INCERTO':
    case 'ALERTA':
      return {
        bgStyle: { backgroundColor: withAlpha(COLORS.accent, 0.05), borderColor: withAlpha(COLORS.accent, 0.2) },
        textStyle: { color: COLORS.accent },
        barStyle: { backgroundColor: COLORS.accent },
        icon: <AlertTriangle className="w-6 h-6" style={{ color: COLORS.accent }} />
      };
    default:
      return {
        bgStyle: { backgroundColor: 'var(--bg-base)', borderColor: 'var(--border)' },
        textStyle: { color: 'var(--foreground)' },
        barStyle: { backgroundColor: 'var(--muted-foreground)' },
        icon: <Info className="w-6 h-6" style={{ color: 'var(--muted-foreground)' }} />
      };
  }
};

const FIELD_LABELS: Record<string, string> = {
  // Identificação
  cpf: 'CPF',
  cnpj: 'CNPJ',
  rg: 'RG',
  nome: 'Nome',
  nome_completo: 'Nome Completo',
  razao_social: 'Razão Social',
  nome_fantasia: 'Nome Fantasia',

  // Dados pessoais
  data_nascimento: 'Data de Nascimento',
  naturalidade: 'Naturalidade',
