interface DocumentPreviewPanelProps {
  documento: Documento;
  documentUrl?: string | null;
}

function DocumentPreviewPanel({ documento, documentUrl }: DocumentPreviewPanelProps) {
  const [numPages, setNumPages] = useState<number | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(1);
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [fileConfig, setFileConfig] = useState<{ url: string; httpHeaders?: Record<string, string> } | null>(null);
  const viewerScrollRef = useRef<HTMLDivElement>(null);
  const pinchDistanceRef = useRef<number | null>(null);
  const dragStartRef = useRef<{ x: number; y: number; scrollLeft: number; scrollTop: number } | null>(null);
  const { Document, Page, isLoading, error } = usePdfViewer();

  const extension = documento.nome.split('.').pop()?.toLowerCase();
  const isPdf = !!documento.content_type?.includes('/pdf') || extension === 'pdf';
  const zoomPercent = Math.round(zoom * 100);

  useEffect(() => {
    setZoom(1);
    setCurrentPage(1);
  }, [documento.id]);

  useEffect(() => {
    if (!documentUrl || !isPdf) {
      setFileConfig(null);
      return;
    }

    getTokenViaAPI().then((token) => {
      setFileConfig({
        url: documentUrl,
        ...(token ? { httpHeaders: { Authorization: `Bearer ${token}` } } : {}),
      });
    });
  }, [documentUrl, isPdf]);

  useEffect(() => {
    if (!documentUrl || isPdf) {
      setImageSrc(null);
      return;
    }

    let objectUrl: string | null = null;

    directApi.get(documentUrl, { responseType: 'blob' }).then(({ data }) => {
      objectUrl = URL.createObjectURL(data);
      setImageSrc(objectUrl);
    });

    return () => {
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [documentUrl, isPdf]);

  const handlePreviousPage = useCallback(() => {
    setCurrentPage((page) => Math.max(page - 1, 1));
  }, []);

  const handleNextPage = useCallback(() => {
    setCurrentPage((page) => Math.min(page + 1, numPages || 1));
  }, [numPages]);

  const handleZoomOut = useCallback(() => {
    setZoom((currentZoom) => Math.max(0.5, Number((currentZoom - 0.15).toFixed(2))));
  }, []);

  const handleZoomIn = useCallback(() => {
    setZoom((currentZoom) => Math.min(2.5, Number((currentZoom + 0.15).toFixed(2))));
  }, []);

  const handleResetZoom = useCallback(() => {
    setZoom(1);
  }, []);

  const handleDownloadDocument = useCallback(async () => {
    if (!documentUrl) return;

    const { data: blob } = await directApi.get(documentUrl, { responseType: 'blob' });
    const objectUrl = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = objectUrl;
    link.download = documento.nome || 'documento';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(objectUrl);
  }, [documentUrl, documento.nome]);

  const handleDocumentDoubleClick = useCallback(() => {
    setZoom((currentZoom) => (currentZoom < 1.6 ? 1.75 : 1));
  }, []);

  const getTouchDistance = useCallback((touches: React.TouchList) => {
    const first = touches.item(0);
    const second = touches.item(1);
    if (!first || !second) return null;

    return Math.hypot(first.clientX - second.clientX, first.clientY - second.clientY);
  }, []);

  const handleTouchStart = useCallback(
    (event: React.TouchEvent<HTMLDivElement>) => {
      if (event.touches.length !== 2) return;
      pinchDistanceRef.current = getTouchDistance(event.touches);
    },
    [getTouchDistance],
  );

  const handleTouchMove = useCallback(
    (event: React.TouchEvent<HTMLDivElement>) => {
      if (event.touches.length !== 2 || !pinchDistanceRef.current) return;

      event.preventDefault();
      const nextDistance = getTouchDistance(event.touches);
      if (!nextDistance) return;

      const delta = nextDistance - pinchDistanceRef.current;
      if (Math.abs(delta) < 6) return;

      setZoom((currentZoom) => {
        const nextZoom = currentZoom + (delta > 0 ? 0.08 : -0.08);
        return Math.max(0.5, Math.min(2.5, Number(nextZoom.toFixed(2))));
      });
      pinchDistanceRef.current = nextDistance;
    },
    [getTouchDistance],
  );

  const handleTouchEnd = useCallback(() => {
    pinchDistanceRef.current = null;
  }, []);

  const handlePointerDown = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
    if (!documentUrl || event.pointerType === 'touch' || event.button !== 0) return;

    const target = event.target as HTMLElement;
    if (target.closest('button,a')) return;

    const viewer = viewerScrollRef.current;
    if (!viewer) return;

    dragStartRef.current = {
      x: event.clientX,
      y: event.clientY,
      scrollLeft: viewer.scrollLeft,
      scrollTop: viewer.scrollTop,
    };
    viewer.setPointerCapture(event.pointerId);
  }, [documentUrl]);

  const handlePointerMove = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
    const dragStart = dragStartRef.current;
    const viewer = viewerScrollRef.current;
    if (!dragStart || !viewer) return;

    event.preventDefault();
    viewer.scrollLeft = dragStart.scrollLeft - (event.clientX - dragStart.x);
    viewer.scrollTop = dragStart.scrollTop - (event.clientY - dragStart.y);
  }, []);

  const handlePointerUp = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
    const viewer = viewerScrollRef.current;
    dragStartRef.current = null;
    if (viewer?.hasPointerCapture(event.pointerId)) viewer.releasePointerCapture(event.pointerId);
  }, []);

  return (
    <aside
      className="flex min-h-[420px] flex-col overflow-hidden rounded-2xl border shadow-sm xl:sticky xl:top-0 xl:h-[calc(90vh-170px)]"
      style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}
    >
      <div className="flex items-center justify-between gap-3 border-b px-4 py-3" style={{ borderColor: COLORS.border }}>
        <div className="min-w-0">
          <p className="font-nexa text-sm font-bold" style={{ color: COLORS.text }}>
            Documento original
          </p>
          <p className="truncate text-xs font-satoshi" title={documento.nome} style={{ color: COLORS.textDim }}>
            {documento.nome}
          </p>
        </div>
        {documentUrl ? (
          <a
            href={documentUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="shrink-0 rounded-lg border px-2.5 py-1.5 text-xs font-satoshi font-semibold hover:brightness-95"
            style={{ borderColor: COLORS.border, color: COLORS.text }}
          >
            Abrir
          </a>
        ) : null}
      </div>

      <div className="relative min-h-0 flex-1" style={{ backgroundColor: 'var(--bg-base)' }}>
        {documentUrl ? (
          <>
            <div
              className="absolute left-4 top-4 z-10 flex items-center gap-1 rounded-2xl border bg-background/95 p-1 shadow-sm backdrop-blur"
              style={{ borderColor: COLORS.border }}
            >
              <Button type="button" variant="ghost" size="icon" className="h-8 w-8" onClick={handleZoomOut} disabled={zoom <= 0.5}>
                <ZoomOut className="h-4 w-4" />
              </Button>
              <button
                type="button"
                onClick={handleResetZoom}
                className="min-w-14 rounded-lg px-2 py-1 text-xs font-satoshi font-semibold hover:bg-muted"
                style={{ color: COLORS.text }}
                title="Resetar zoom"
              >
                {zoomPercent}%
              </button>
              <Button type="button" variant="ghost" size="icon" className="h-8 w-8" onClick={handleZoomIn} disabled={zoom >= 2.5}>
                <ZoomIn className="h-4 w-4" />
              </Button>
              <div className="mx-1 h-5 w-px bg-border" />
              <Button type="button" variant="ghost" size="icon" className="h-8 w-8" onClick={handleDownloadDocument} title="Baixar documento">
                <Download className="h-4 w-4" />
              </Button>
            </div>

            <span className="absolute right-4 top-7 z-10 hidden rounded-full bg-background/90 px-3 py-1 text-[11px] font-satoshi shadow-sm backdrop-blur md:block" style={{ color: COLORS.textDim }}>
              Use o zoom para conferir detalhes do documento.
            </span>
          </>
        ) : null}

        <div
          ref={viewerScrollRef}
          className="flex h-full min-h-0 cursor-grab items-start justify-center overflow-auto px-4 pb-4 pt-20 active:cursor-grabbing"
          style={{ touchAction: 'pan-x pan-y' }}
          onDoubleClick={documentUrl ? handleDocumentDoubleClick : undefined}
          onPointerDown={documentUrl ? handlePointerDown : undefined}
          onPointerMove={documentUrl ? handlePointerMove : undefined}
          onPointerUp={documentUrl ? handlePointerUp : undefined}
          onPointerCancel={documentUrl ? handlePointerUp : undefined}
          onTouchStart={documentUrl ? handleTouchStart : undefined}
          onTouchMove={documentUrl ? handleTouchMove : undefined}
          onTouchEnd={documentUrl ? handleTouchEnd : undefined}
          onTouchCancel={documentUrl ? handleTouchEnd : undefined}
        >
        {!documentUrl ? (
          <p className="max-w-xs text-center text-sm font-satoshi" style={{ color: COLORS.textDim }}>
            Documento sem arquivo disponível para visualização.
          </p>
        ) : isPdf ? (
          <div className="flex min-h-full w-full flex-col items-center gap-3">
            <div className="flex items-center gap-2 rounded-xl border bg-background px-3 py-2" style={{ borderColor: COLORS.border }}>
              <Button type="button" variant="ghost" size="sm" onClick={handlePreviousPage} disabled={currentPage <= 1}>
                Anterior
              </Button>
              <span className="text-xs font-satoshi" style={{ color: COLORS.textDim }}>
                Página {currentPage} de {numPages || 1}
              </span>
              <Button type="button" variant="ghost" size="sm" onClick={handleNextPage} disabled={currentPage >= (numPages || 1)}>
                Próxima
              </Button>
            </div>

            {isLoading || !Document || !Page || !fileConfig ? (
              <div className="flex flex-1 items-center justify-center gap-2 text-sm" style={{ color: COLORS.textDim }}>
                <Loader2 className="h-4 w-4 animate-spin" />
                Carregando PDF
              </div>
            ) : error ? (
              <p className="text-center text-sm" style={{ color: COLORS.red }}>
                Não foi possível carregar o PDF.
              </p>
            ) : (
              <Document file={fileConfig} onLoadSuccess={({ numPages: pages }: { numPages: number }) => setNumPages(pages)}>
                <Page pageNumber={currentPage} width={Math.round(520 * zoom)} renderTextLayer={false} renderAnnotationLayer={false} />
              </Document>
            )}
          </div>
        ) : imageSrc ? (
          <img
            src={imageSrc}
            alt={documento.nome}
            className="max-w-none rounded-xl object-contain transition-[width]"
            style={{ width: `${zoom * 100}%`, height: 'auto' }}
          />
        ) : (
          <div className="flex items-center gap-2 text-sm" style={{ color: COLORS.textDim }}>
            <Loader2 className="h-4 w-4 animate-spin" />
            Carregando imagem
          </div>
        )}
        </div>
      </div>
    </aside>
  );
}

export function AIAnalysisModal({
  isOpen,
  onClose,
  documento,
  analise,
  onApprove,
  onReject,
  onAnalysisComplete,
  isProcessing = false,
  documentUrl,
  showDocumentActions = true,
  showAuditFeedback = true,
}: AIAnalysisModalProps) {
  const queryClient = useQueryClient();
  const [isReanalyzing, setIsReanalyzing] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);
  const [feedbackObservation, setFeedbackObservation] = useState('');
  const [feedbackCategory, setFeedbackCategory] = useState<DocumentoAnaliseFeedbackCategoria>('OUTRO');
  const [feedbackDecision, setFeedbackDecision] = useState<DocumentoAnaliseFeedbackDecisao | ''>('');
  const [isWaitingForReanalysis, setIsWaitingForReanalysis] = useState(false);
  const reanalysisStartedAtRef = useRef<number | null>(null);

  const analiseQueryKey = ['documento-analise', documento?.id];

  // Internal query to refetch analysis when modal is open
  const {
    data: analysisDetail,
    refetch: refetchAnalise,
  } = useQuery<DocumentoAnaliseDetail>({
    queryKey: analiseQueryKey,
    queryFn: () => getDocumentoAnaliseDetail(documento!.id),
    enabled: isOpen && !!documento?.id,
    refetchInterval: false, // Manual refetch only
    staleTime: 0, // Always fresh
  });

  // Use live analysis from query if available, otherwise use prop
  const displayAnalise = analysisDetail?.analise_atual || analise;
  const analysisHistory = analysisDetail?.historico ?? [];
  const displayAnaliseStatus = displayAnalise?.status;
  const isPendingManualReview =
    !!documento?.analise_ia_pendente_revisao_manual ||
    (displayAnalise?.status === 'CONCLUIDO' &&
      !displayAnalise.auto_aprovado &&
      !displayAnalise.auto_rejeitado &&
      typeof displayAnalise.confianca === 'number' &&
      displayAnalise.confianca < 95);

  const {
    data: feedbacks = [],
    refetch: refetchFeedbacks,
  } = useQuery({
    queryKey: ['documento-analise-feedbacks', documento?.id],
    queryFn: () => getDocumentoAnaliseFeedbacks(documento!.id),
    enabled: showAuditFeedback && isOpen && !!documento?.id,
  });

  const createFeedbackMutation = useMutation({
    mutationFn: () =>
      createDocumentoAnaliseFeedback(documento!.id, {
        observacao: feedbackObservation,
        categoria: feedbackCategory,
        decisao_humana: feedbackDecision || null,
        aproveitar_para_treinamento: true,
      }),
    onSuccess: () => {
      setFeedbackObservation('');
      setFeedbackCategory('OUTRO');
      setFeedbackDecision('');
      setActionError(null);
      refetchFeedbacks();
    },
    onError: () => {
      setActionError('Erro ao salvar feedback para melhoria da IA');
    },
  });

  // Poll every 2 seconds while analyzing as fallback for WebSocket
  useEffect(() => {
    const isAnalyzing = !displayAnaliseStatus || displayAnaliseStatus === 'PENDENTE' || displayAnaliseStatus === 'PROCESSANDO';

    if (!isOpen || !documento?.id || (!isAnalyzing && !isWaitingForReanalysis)) {
      return;
    }

    const interval = setInterval(() => {
      refetchAnalise();
    }, 2000);

    return () => clearInterval(interval);
  }, [isOpen, documento?.id, displayAnaliseStatus, isWaitingForReanalysis, refetchAnalise]);

  useEffect(() => {
    if (!isWaitingForReanalysis || !displayAnalise || !reanalysisStartedAtRef.current) return;
    if (displayAnalise.status !== 'CONCLUIDO' && displayAnalise.status !== 'ERRO') return;

    const completedAt = new Date(displayAnalise.processado_em || displayAnalise.updated_at).getTime();
    if (!Number.isFinite(completedAt) || completedAt < reanalysisStartedAtRef.current) return;

    setIsWaitingForReanalysis(false);
    reanalysisStartedAtRef.current = null;
    onAnalysisComplete?.();
  }, [displayAnalise, isWaitingForReanalysis, onAnalysisComplete]);

  useEffect(() => {
    setFeedbackObservation('');
    setFeedbackCategory('OUTRO');
    setFeedbackDecision('');
    setActionError(null);
    setIsWaitingForReanalysis(false);
    reanalysisStartedAtRef.current = null;
  }, [documento?.id]);

  // Listen for document status updates via WebSocket
  useDocumentoWebSocket({
    documento_id: documento?.id || 0,
    enabled: isOpen && !!documento?.id,
    onStatusUpdate: (event) => {
      // Refetch analysis when document status changes or analysis completes
      if (event.status === 'APROVADO' || event.status === 'REPROVADO' || event.type === 'analise_concluida') {
        refetchAnalise();
        onAnalysisComplete?.();
      }
    },
  });

  // Guard: must be after all hooks
  if (!documento) return null;

  const handleReanalyze = async () => {
    if (!documento) return;
    setIsReanalyzing(true);
    setActionError(null);
    try {
      reanalysisStartedAtRef.current = Date.now();
      await reAnalisarDocumento(documento.id);
      queryClient.setQueryData<DocumentoAnaliseDetail | undefined>(['documento-analise', documento.id], (current) => {
        const analysisSnapshot = current?.analise_atual || analise;
        if (!analysisSnapshot) return current;
        return {
          ...(current ?? {
            documento_id: documento.id,
            documento_nome: documento.nome,
            historico: [],
            total_analises: 0,
          }),
          analise_atual: {
            ...analysisSnapshot,
            status: 'PENDENTE',
            recomendacao: null,
            confianca: null,
            auto_aprovado: false,
            auto_rejeitado: false,
            erro: '',
            processado_em: null,
            updated_at: new Date().toISOString(),
          },
        };
      });
      setIsWaitingForReanalysis(true);
      onAnalysisComplete?.();
    } catch (error) {
      reanalysisStartedAtRef.current = null;
      setIsWaitingForReanalysis(false);
      setActionError('Erro ao re-analisar documento');
      console.error(error);
    } finally {
      setIsReanalyzing(false);
    }
  };

  const handleApprove = async () => {
    if (!documento) return;
    try {
      setActionError(null);
      await onApprove(documento.id);
      onClose();
    } catch (error) {
      setActionError('Erro ao aprovar documento');
      console.error(error);
    }
  };

  const handleReject = async () => {
    if (!documento) return;
    try {
      setActionError(null);
      await onReject(documento.id);
      onClose();
    } catch (error) {
      setActionError('Erro ao rejeitar documento');
      console.error(error);
    }
  };

  const handleSubmitFeedback = () => {
    if (!documento || feedbackObservation.trim().length < 10) return;
    createFeedbackMutation.mutate();
  };

  const config = displayAnalise ? getRecommendationConfig(displayAnalise.recomendacao) : getRecommendationConfig(null);

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent 
        className="max-w-[96vw] xl:max-w-7xl w-[96vw] max-h-[90vh] flex flex-col p-0 gap-0 overflow-hidden shadow-2xl rounded-2xl"
        style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}
      >
        {/* Header Design System Compatible */}
        <DialogHeader 
          className="m-0 border-b px-4 py-4 sm:px-6 sm:py-5"
          style={{ borderColor: COLORS.border }}
        >
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex min-w-0 items-center gap-3 sm:gap-4">
              <div 
                className="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border sm:h-14 sm:w-14"
                style={{ backgroundColor: 'var(--bg-base)', borderColor: COLORS.border, boxShadow: 'var(--shadow-sm)' }}
              >
                <Image
                  src="/intelligence/logo_revamp.png"
                  alt="Ativos Intelligence"
                  width={36}
                  height={36}
                  className="object-contain"
                />
              </div>
              <div className="flex min-w-0 flex-col text-left">
                <DialogTitle className="font-nexa text-lg font-bold tracking-tight sm:text-xl" style={{ color: COLORS.text }}>
                  Análise de Documento
                </DialogTitle>
                <p className="mt-0.5 max-w-full truncate font-satoshi text-sm font-medium" style={{ color: COLORS.textDim }} title={documento.nome}>
                  {documento.nome}
                </p>
              </div>
            </div>
            {documento.proposta_uuid ? (
              <a
                href={`/crm/gerencial-broker/${documento.proposta_uuid}`}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex h-10 w-full items-center justify-center gap-2 rounded-xl border px-3 font-satoshi text-sm font-semibold transition-all duration-200 hover:brightness-95 active:scale-95 sm:w-auto"
                style={{ borderColor: COLORS.border, color: COLORS.text }}
              >
                <ExternalLink className="h-4 w-4" />
                Ver proposta
              </a>
            ) : null}
          </div>
        </DialogHeader>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto px-4 py-4 sm:px-6 sm:py-6" style={{ backgroundColor: 'var(--bg-base)' }}>
          <div className="grid max-w-full gap-6 xl:grid-cols-[minmax(420px,0.95fr)_minmax(0,1.05fr)]">
            <DocumentPreviewPanel documento={documento} documentUrl={documentUrl} />
            <div className="flex min-w-0 flex-col gap-6">
            <Tabs defaultValue="resumo" className="min-w-0">
              <TabsList className="mb-4 grid h-auto w-full grid-cols-2 rounded-2xl bg-muted/40 p-1">
                <TabsTrigger value="resumo" className="rounded-xl font-satoshi">
                  Resumo da análise
                </TabsTrigger>
                <TabsTrigger value="historico" className="rounded-xl font-satoshi">
                  Histórico ({analysisHistory.length})
                </TabsTrigger>
              </TabsList>

              <TabsContent value="resumo" className="mt-0 space-y-6 focus-visible:ring-0">
            {isPendingManualReview ? (
              <div
                className="rounded-2xl border p-4 shadow-sm"
                style={{ backgroundColor: withAlpha(COLORS.accent, 0.08), borderColor: withAlpha(COLORS.accent, 0.24) }}
              >
                <div className="flex items-start gap-3">
                  <div className="mt-0.5 rounded-full p-2" style={{ backgroundColor: COLORS.card, color: COLORS.accent }}>
                    <AlertTriangle className="h-5 w-5" />
                  </div>
                  <div className="space-y-1">
                    <p className="font-nexa text-sm font-bold" style={{ color: COLORS.text }}>
                      Revisão manual necessária
                    </p>
                    <p className="text-sm font-satoshi leading-relaxed" style={{ color: COLORS.textDim }}>
                      A IA não aplicou decisão automática com confiança suficiente. Compare o documento com a análise e escolha
                      explicitamente aprovar, rejeitar ou reanalisar.
                    </p>
                  </div>
                </div>
              </div>
            ) : null}

            {!displayAnalise ? (
              <div className="flex flex-col items-center justify-center py-16 gap-4">
                <div 
                  className="relative w-16 h-16 flex items-center justify-center rounded-full"
                  style={{ backgroundColor: withAlpha(COLORS.textDim, 0.1), color: COLORS.textDim }}
                >
                  <Info className="w-8 h-8" />
                </div>
                <div className="text-center max-w-md">
                  <p className="text-base font-bold font-satoshi" style={{ color: COLORS.text }}>Nenhuma análise disponível</p>
                  <p className="text-sm font-satoshi mt-1" style={{ color: COLORS.textDim }}>
                    Clique em <strong>Re-analisar</strong> para iniciar a análise automática do documento pela IA.
                  </p>
                </div>
              </div>
            ) : displayAnalise.status === 'PENDENTE' ? (
              <div className="flex flex-col items-center justify-center py-16 gap-4">
                <div 
                  className="relative w-16 h-16 flex items-center justify-center rounded-full"
                  style={{ backgroundColor: withAlpha(COLORS.blue, 0.1), color: COLORS.blue }}
                >
                  <Loader2 className="w-8 h-8 animate-spin" />
                </div>
                <div className="text-center max-w-md">
                  <p className="text-base font-bold font-satoshi" style={{ color: COLORS.text }}>Análise agendada...</p>
                  <p className="text-sm font-satoshi mt-1" style={{ color: COLORS.textDim }}>
                    A análise foi enfileirada e será processada em breve.
                  </p>
                </div>
              </div>
            ) : displayAnalise.status === 'PROCESSANDO' ? (
              <div className="flex flex-col items-center justify-center py-16 gap-4">
                <div 
                  className="relative w-16 h-16 flex items-center justify-center rounded-full"
                  style={{ backgroundColor: withAlpha(COLORS.blue, 0.1), color: COLORS.blue }}
                >
                  <Loader2 className="w-8 h-8 animate-spin" />
                </div>
                <div className="text-center">
                  <p className="text-base font-bold font-satoshi" style={{ color: COLORS.text }}>Analisando documento...</p>
                  <p className="text-sm font-satoshi mt-1" style={{ color: COLORS.textDim }}>Processando conteúdo e validando informações</p>
                </div>
              </div>
            ) : displayAnalise.status === 'ERRO' ? (
              <div 
                className="p-5 rounded-2xl flex gap-4 items-start shadow-sm border"
                style={{ backgroundColor: withAlpha(COLORS.red, 0.05), borderColor: withAlpha(COLORS.red, 0.2) }}
              >
                <div className="p-2 rounded-full shadow-sm shrink-0" style={{ backgroundColor: COLORS.card, color: COLORS.red }}>
                  <AlertTriangle className="w-6 h-6" />
                </div>
                <div className="pt-0.5 font-satoshi">
                  <h3 className="font-bold text-base" style={{ color: COLORS.red }}>Erro na análise</h3>
                  <p className="text-sm mt-1 leading-relaxed" style={{ color: COLORS.redDim || COLORS.red }}>
                    {displayAnalise.erro || 'Ocorreu um erro desconhecido durante o processamento do documento.'}
                  </p>
                </div>
              </div>
            ) : (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-6">
                {/* 1. Status & Confiança Hero Card */}
                <div 
                  className="flex flex-col sm:flex-row sm:items-center justify-between gap-5 p-5 rounded-2xl border shadow-sm"
                  style={config.bgStyle}
                >
                  <div className="flex items-center gap-4">
                    <div className="p-3 rounded-2xl shadow-sm shrink-0" style={{ backgroundColor: COLORS.card }}>
                      {config.icon}
                    </div>
                    <div className="flex flex-col font-satoshi">
                      <span className="text-[11px] font-bold uppercase tracking-widest opacity-80" style={config.textStyle}>
                        Resultado da Análise
                      </span>
                      <span className="text-xl font-black font-nexa tracking-tight" style={config.textStyle}>
                        {displayAnalise.recomendacao || 'N/A'}
                      </span>
                    </div>
                  </div>

                  {displayAnalise.confianca !== null && (
                    <div 
                      className="flex flex-col gap-2 w-full sm:w-64 shrink-0 p-3 rounded-xl border"
                      style={{ backgroundColor: withAlpha(COLORS.card, 0.4), borderColor: withAlpha(COLORS.card, 0.6) }}
                    >
                      <div className="flex justify-between items-center font-satoshi">
                        <span className="text-xs font-bold uppercase tracking-wider" style={config.textStyle}>Confiança</span>
                        <span className="text-sm font-black" style={config.textStyle}>{displayAnalise.confianca.toFixed(0)}%</span>
                      </div>
                      <div className="w-full rounded-full h-2.5 shadow-inner overflow-hidden" style={{ backgroundColor: withAlpha(COLORS.card, 0.8) }}>
                        <div
                          className="h-full rounded-full transition-all duration-1000 ease-out"
                          style={{ width: `${displayAnalise.confianca}%`, ...config.barStyle }}
                        />
                      </div>
                    </div>
                  )}
                </div>

                {/* 2. Resumo (if exists) */}
                {displayAnalise.resumo && (
                  <div 
                    className="relative p-5 rounded-2xl border shadow-sm overflow-hidden"
                    style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}
                  >
                    <div className="absolute left-0 top-0 bottom-0 w-1.5" style={{ backgroundColor: COLORS.blue }}></div>
                    <p className="text-sm font-satoshi font-medium leading-relaxed pl-2" style={{ color: COLORS.text }}>
                      {displayAnalise.resumo}
                    </p>
                  </div>
                )}

                {/* 3. Campos Extraídos */}
                {Object.keys(displayAnalise.campos_extraidos).length > 0 && (
                  <div className="space-y-3">
                    <div className="flex items-center gap-2 px-1">
                      <Sparkles className="w-4 h-4" style={{ color: COLORS.blue }} />
                      <h4 className="text-sm font-nexa font-bold" style={{ color: COLORS.text }}>Dados Extraídos</h4>
                    </div>
                    <div 
                      className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3 p-4 rounded-2xl border shadow-sm"
                      style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}
                    >
                      {Object.entries(displayAnalise.campos_extraidos).map(([key, value]) => (
                        <div 
                          key={key} 
                          className="flex flex-col gap-1.5 p-3 rounded-xl border transition-colors group hover:brightness-95"
                          style={{ backgroundColor: 'var(--bg-base)', borderColor: COLORS.border }}
                        >
                          <span className="text-[10px] font-bold font-satoshi uppercase tracking-widest" style={{ color: COLORS.textDim }}>{humanizeFieldName(key)}</span>
                          <span className="text-sm font-semibold font-satoshi wrap-break-word" style={{ color: COLORS.text }}>{String(value)}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 4. Problemas Detectados */}
                {displayAnalise.problemas.length > 0 && (
                  <div className="space-y-3">
                    <div className="flex items-center gap-2 px-1">
                      <AlertTriangle className="w-4 h-4" style={{ color: COLORS.red }} />
                      <h4 className="text-sm font-nexa font-bold" style={{ color: COLORS.red }}>Problemas Detectados</h4>
                    </div>
                    <div className="flex flex-col gap-2">
                      {displayAnalise.problemas.map((problema, idx) => (
                        <div 
                          key={idx} 
                          className="flex items-start gap-3 p-4 rounded-xl border shadow-sm"
                          style={{ backgroundColor: withAlpha(COLORS.red, 0.05), borderColor: withAlpha(COLORS.red, 0.15) }}
                        >
                          <div className="mt-1.5 w-1.5 h-1.5 rounded-full shrink-0" style={{ backgroundColor: COLORS.red }} />
                          <span className="text-sm font-satoshi font-medium leading-relaxed" style={{ color: COLORS.redDim || COLORS.red }}>{problema}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 5. Sugestões */}
                {displayAnalise.sugestoes && displayAnalise.sugestoes.length > 0 && (
                  <div className="space-y-3">
                    <div className="flex items-center gap-2 px-1">
                      <Lightbulb className="w-4 h-4" style={{ color: COLORS.accent }} />
                      <h4 className="text-sm font-nexa font-bold" style={{ color: COLORS.accent }}>Sugestões de Ação</h4>
                    </div>
                    <div className="flex flex-col gap-2">
                      {displayAnalise.sugestoes.map((sugestao, idx) => (
                        <div 
                          key={idx} 
                          className="flex items-start gap-3 p-4 rounded-xl border shadow-sm"
                          style={{ backgroundColor: withAlpha(COLORS.accent, 0.05), borderColor: withAlpha(COLORS.accent, 0.15) }}
                        >
                          <div className="mt-1 w-4 h-4 shrink-0" style={{ color: COLORS.accent }}>
                            <CheckCircle className="w-4 h-4" />
                          </div>
                          <span className="text-sm font-satoshi font-medium leading-relaxed" style={{ color: COLORS.accentDim || COLORS.accent }}>{sugestao}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 6. Metadata */}
                {(displayAnalise.processado_em || displayAnalise.auto_aprovado) && (
                  <div className="flex flex-wrap items-center gap-4 pt-4 px-1">
                    {displayAnalise.processado_em && (
                      <div 
                        className="flex items-center gap-1.5 text-[11px] font-satoshi font-bold px-2.5 py-1 rounded-md"
                        style={{ backgroundColor: withAlpha(COLORS.textDim, 0.1), color: COLORS.textDim }}
                      >
                        <Info className="w-3.5 h-3.5" />
                        <span>Processado em: {new Date(displayAnalise.processado_em).toLocaleString('pt-BR')}</span>
                      </div>
                    )}
                    {displayAnalise.auto_aprovado && (
                      <div 
                        className="flex items-center gap-1.5 text-[11px] font-satoshi font-bold px-2.5 py-1 rounded-md border"
                        style={{ backgroundColor: withAlpha(COLORS.green, 0.1), borderColor: withAlpha(COLORS.green, 0.2), color: COLORS.green }}
                      >
                        <CheckCircle className="w-3.5 h-3.5" />
                        <span>Auto-aprovado pela IA</span>
                      </div>
                    )}
                    {displayAnalise.auto_rejeitado && (
                      <div
                        className="flex items-center gap-1.5 text-[11px] font-satoshi font-bold px-2.5 py-1 rounded-md border"
                        style={{ backgroundColor: withAlpha(COLORS.red, 0.1), borderColor: withAlpha(COLORS.red, 0.2), color: COLORS.red }}
                      >
                        <AlertTriangle className="w-3.5 h-3.5" />
                        <span>Auto-rejeitado pela IA</span>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {showAuditFeedback && (
            <Accordion
              type="single"
              collapsible
              className="rounded-2xl border shadow-sm overflow-hidden"
              style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}
            >
              <AccordionItem value="feedback" className="border-0">
                <AccordionTrigger
                  className="items-start gap-2 px-4 py-4 hover:no-underline hover:bg-transparent sm:px-5 [&>svg]:mt-1 [&>svg]:shrink-0 [&>svg]:text-current"
                  style={{ backgroundColor: withAlpha(COLORS.blue, 0.05) }}
                >
                  <div className="flex min-w-0 flex-1 flex-col gap-1 text-left">
                    <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1.5">
                      <Lightbulb className="h-4 w-4 shrink-0" style={{ color: COLORS.blue }} />
                      <span className="min-w-0 text-sm font-nexa font-bold" style={{ color: COLORS.text }}>
                        Feedback para melhoria da IA
                      </span>
                      <Badge
                        variant="outline"
                        className="inline-flex h-auto min-h-5 shrink-0 items-center whitespace-nowrap rounded-full px-2 py-0.5 text-[10px] font-semibold leading-none"
                        style={{ borderColor: withAlpha(COLORS.blue, 0.24), color: COLORS.blue }}
                      >
                        Curadoria pendente
                      </Badge>
                    </div>
                    <p className="text-xs font-satoshi leading-relaxed" style={{ color: COLORS.textDim }}>
                      Registre aprendizados úteis para análise de documentos. Nada é aplicado automaticamente.
                    </p>
                  </div>
                </AccordionTrigger>

                <AccordionContent className="pb-0">
              <div className="space-y-4 p-5">
                {feedbacks.length > 0 ? (
                  <div className="space-y-2">
                    <p className="text-xs font-bold uppercase tracking-widest" style={{ color: COLORS.textDim }}>
                      Observações recentes
                    </p>
                    <div className="space-y-2">
                      {feedbacks.slice(0, 3).map((feedback) => (
                        <div
                          key={feedback.id}
                          className="rounded-xl border p-3"
                          style={{ backgroundColor: 'var(--bg-base)', borderColor: COLORS.border }}
                        >
                          <div className="mb-1 flex flex-wrap items-center gap-2">
                            <Badge variant="secondary" className="text-[10px]">
                              {feedback.categoria_display}
                            </Badge>
                            <span className="text-[11px] font-satoshi" style={{ color: COLORS.textDim }}>
                              {feedback.criado_por_nome || 'Revisor'} ·{' '}
                              {new Date(feedback.criado_em).toLocaleString('pt-BR')}
                            </span>
                          </div>
                          <p className="text-sm font-satoshi leading-relaxed" style={{ color: COLORS.text }}>
                            {feedback.observacao}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : null}

                <div className="space-y-3">
                  <div className="grid gap-3 sm:grid-cols-2">
                    <div className="space-y-2">
                      <label className="text-xs font-bold uppercase tracking-widest" style={{ color: COLORS.textDim }}>
                        Categoria
                      </label>
                      <select
                        value={feedbackCategory}
                        onChange={(event) => setFeedbackCategory(event.target.value as DocumentoAnaliseFeedbackCategoria)}
                        className="h-11 w-full rounded-xl border px-3 text-sm font-satoshi"
                        style={{ backgroundColor: 'var(--bg-base)', borderColor: COLORS.border, color: COLORS.text }}
                      >
                        {FEEDBACK_CATEGORIES.map((category) => (
                          <option key={category.value} value={category.value}>
                            {category.label}
                          </option>
                        ))}
                      </select>
                    </div>

                    <div className="space-y-2">
                      <label className="text-xs font-bold uppercase tracking-widest" style={{ color: COLORS.textDim }}>
                        Decisão humana
                      </label>
                      <select
                        value={feedbackDecision}
                        onChange={(event) => setFeedbackDecision(event.target.value as DocumentoAnaliseFeedbackDecisao | '')}
                        className="h-11 w-full rounded-xl border px-3 text-sm font-satoshi"
                        style={{ backgroundColor: 'var(--bg-base)', borderColor: COLORS.border, color: COLORS.text }}
                      >
                        <option value="">Não informar</option>
                        {HUMAN_DECISIONS.map((decision) => (
                          <option key={decision.value} value={decision.value}>
                            {decision.label}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-bold uppercase tracking-widest" style={{ color: COLORS.textDim }}>
                      Observação do revisor
                    </label>
                    <Textarea
                      value={feedbackObservation}
                      onChange={(event) => setFeedbackObservation(event.target.value)}
                      maxLength={2000}
                      placeholder="Ex.: Conta de luz recente em nome do cedente deve ser aceita como comprovante de residência."
                      className="min-h-[96px] rounded-xl font-satoshi"
                    />
                    <p className="text-[11px] font-satoshi" style={{ color: COLORS.textDim }}>
                      {feedbackObservation.trim().length}/2000 caracteres · mínimo de 10 para salvar.
                    </p>
                  </div>
                </div>

                <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                  <p className="text-[11px] font-satoshi" style={{ color: COLORS.textDim }}>
                    O feedback entra na fila de curadoria para treinamento e não altera a análise atual automaticamente.
                  </p>
                  <Button
                    type="button"
                    onClick={handleSubmitFeedback}
                    disabled={createFeedbackMutation.isPending || feedbackObservation.trim().length < 10}
                    className="gap-2 rounded-xl font-satoshi font-semibold transition-all duration-200 active:scale-95"
                    style={{ backgroundColor: COLORS.accent, color: 'white' }}
                  >
                    {createFeedbackMutation.isPending ? (
                      <>
                        <Loader2 className="w-4 h-4 animate-spin" />
                        Salvando...
                      </>
                    ) : (
                      <>
                        <Lightbulb className="w-4 h-4" />
                        Salvar feedback
                      </>
                    )}
                  </Button>
                </div>
              </div>
                </AccordionContent>
              </AccordionItem>
            </Accordion>
            )}

            {actionError && (
              <div 
                className="mt-2 p-4 rounded-xl border flex items-center gap-3 animate-in fade-in"
                style={{ backgroundColor: withAlpha(COLORS.red, 0.05), borderColor: withAlpha(COLORS.red, 0.2), color: COLORS.red }}
              >
                <AlertTriangle className="w-5 h-5 shrink-0" />
                <span className="text-sm font-satoshi font-medium">{actionError}</span>
              </div>
            )}
              </TabsContent>

              <TabsContent value="historico" className="mt-0 focus-visible:ring-0">
                <AnalysisHistoryList history={analysisHistory} />
              </TabsContent>
            </Tabs>
            </div>
          </div>
        </div>

        {/* Footer Actions */}
        <DialogFooter 
          className="px-6 py-4 border-t flex flex-col sm:flex-row gap-3 sm:justify-between m-0"
          style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}
        >
          {showDocumentActions ? (
            <>
              <div className="flex-1">
                <Button
                  variant="outline"
                  onClick={handleReanalyze}
                  disabled={isReanalyzing}
                  className="w-full sm:w-auto gap-2 rounded-xl transition-all duration-200"
                  style={{ borderColor: COLORS.border, color: COLORS.text }}
                >
                  {isReanalyzing ? (
                    <><Loader2 className="w-4 h-4 animate-spin" /> Re-analisando...</>
                  ) : (
                    <><RotateCw className="w-4 h-4" /> Re-analisar</>
                  )}
                </Button>
              </div>

              <div className="flex flex-col sm:flex-row gap-2 sm:gap-3 w-full sm:w-auto">
                <Button
                  variant="ghost"
                  onClick={onClose}
                  className="gap-2 rounded-xl order-last sm:order-first transition-all duration-200 hover:brightness-95"
                  style={{ color: COLORS.textDim }}
                >
                  Cancelar
                </Button>

                {displayAnalise?.recomendacao !== 'REPROVADO' && (
                  <Button
                    onClick={handleReject}
                    disabled={isProcessing || !documento}
                    className="gap-2 rounded-xl shadow-sm transition-all duration-200 hover:opacity-90 active:scale-95"
                    style={{ backgroundColor: COLORS.red, color: 'white' }}
                  >
                    {isProcessing ? (
                      <><Loader2 className="w-4 h-4 animate-spin" /> Rejeitando...</>
                    ) : (
                      <><AlertTriangle className="w-4 h-4" /> Rejeitar</>
                    )}
                  </Button>
                )}

                {displayAnalise?.recomendacao !== 'APROVADO' && (
                  <Button
                    onClick={handleApprove}
                    disabled={isProcessing || !documento}
                    className="gap-2 rounded-xl shadow-sm transition-all duration-200 hover:opacity-90 active:scale-95"
                    style={{ 
                      backgroundColor: displayAnalise?.recomendacao === 'REPROVADO' ? COLORS.accent : COLORS.green, 
                      color: 'white' 
                    }}
                  >
                    {isProcessing ? (
                      <><Loader2 className="w-4 h-4 animate-spin" /> Aprovando...</>
                    ) : (
                      <><CheckCircle className="w-4 h-4" /> {displayAnalise?.recomendacao === 'REPROVADO' ? 'Forçar Aprovação' : 'Aprovar'}</>
                    )}
                  </Button>
                )}
              </div>
            </>
          ) : (
            <div className="flex w-full justify-end">
              <Button
                variant="outline"
                onClick={onClose}
                className="gap-2 rounded-xl"
                style={{ borderColor: COLORS.border, color: COLORS.text }}
              >
                Fechar
              </Button>
            </div>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

