'use client';

import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { PdfDocumentViewer } from './PdfDocumentViewer';

interface PDFViewerModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  fileUrl: string;
  fileName?: string;
  canDownload?: boolean;
  /** Optional protected URL used only for downloading (preview can remain unmarked). */
  downloadUrl?: string;
}

export function PDFViewerModal({
  open,
  onOpenChange,
  fileUrl,
  fileName,
  canDownload = true,
  downloadUrl,
}: PDFViewerModalProps) {
  const [isFullscreen, setIsFullscreen] = useState(false);

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) setIsFullscreen(false);
        onOpenChange(next);
      }}
    >
      <DialogContent
        className={`flex h-[90vh] w-full flex-col p-4 ${
          isFullscreen ? 'h-[95vh] max-w-[95vw]' : 'max-w-5xl'
        }`}
      >
        <DialogHeader className="border-b pb-4">
          <DialogTitle className="text-xl font-semibold text-title">
            {fileName ? `Visualização: ${fileName}` : 'Visualização do PDF'}
          </DialogTitle>
        </DialogHeader>

        <PdfDocumentViewer
          active={open && !!fileUrl}
          fileUrl={fileUrl}
          fileName={fileName}
          canDownload={canDownload}
          downloadUrl={downloadUrl}
          variant="modal"
          expanded={isFullscreen}
          onExpandedChange={setIsFullscreen}
          className="min-h-0 flex-1"
          showKeyboardHints
        />
      </DialogContent>
    </Dialog>
  );
}

