'use client';

import { CreateNewEsteiraModal } from '@/components/Modals/CreateNewEsteira';
import { brokerSlotSubtitle } from '@/functions/broker/broker-document-exigencias';
import { verifyCedenteType } from '@/functions/verifiers/verifyCedenteType';
import { cn } from '@/lib/utils';
import { docTypes } from '@/types/broker';
import dynamic from 'next/dynamic';
import Image from 'next/image';
import { type ReactNode } from 'react';
import { useBrokerDocumentPanel } from '../_hooks/useBrokerDocumentPanel';
import { DocumentsBentoAddDocCard } from './DocumentsBentoAddDocCard';
import { DocumentsBentoDocCard } from './DocumentsBentoDocCard';
import {
    documentsBentoGridCellClass,
    documentsBentoGridClass,
    documentsBentoPlaceholderClass,
} from './bentoCedenteClasses';

const OFICIO_REQUISITORIO_DOC_TYPE = 'OFICIO_REQUISITORIO';

const LinkEsteiraToExtratoModal = dynamic(
    () =>
        import('@/components/Modals/LinkEsteiraToExtratoModal').then(
            (module) => module.LinkEsteiraToExtratoModal,
        ),
    { ssr: false },
);

interface DocumentsBentoCatalogProps {
    isLocked?: boolean;
}

function DocumentsBentoGrid({
    children,
    isLocked,
}: {
    children: ReactNode;
    isLocked?: boolean;
}) {
    return (
        <div className={cn(documentsBentoGridClass, isLocked && 'pointer-events-none opacity-50')}>
            {children}
        </div>
    );
}

function DocumentsBentoGridCell({ children }: { children: ReactNode }) {
    return <div className={documentsBentoGridCellClass}>{children}</div>;
}

function DocumentsBentoPlaceholder({
    alt,
    message,
    action,
}: {
    alt: string;
    message: string;
    action?: ReactNode;
}) {
    return (
        <div className={documentsBentoPlaceholderClass}>
            <Image src="/images/illustration/documents.svg" alt={alt} width={100} height={84} />
            <p>{message}</p>
            {action}
        </div>
    );
}

export function DocumentsBentoCatalog({ isLocked }: DocumentsBentoCatalogProps) {
    const panel = useBrokerDocumentPanel();
    const {
        cedenteType,
        cedenteData,
        linkedEsteirasCedente,
        linkedEsteirasRepresentante,
        oficioEsteirasAtivas,
        esteiraDocsCedente,
        esteiraDocsRepresentante,
        conditionalCedenteSlots,
        activeCedenteEsteiraId,
        filteredPfDocs,
        representantePfDocs,
        hasActiveEsteiraRepresentante,
        loadingStates,
        docFunctions,
        findDocumentByType,
        findCustomDocuments,
        findDocForSlot,
        slotToDocType,
        slotLoadingKey,
        getActiveEsteiraId,
    } = panel;

    const esteiraId =
        activeCedenteEsteiraId ?? (linkedEsteirasCedente?.[0]?.id as number | undefined);

    const cardProps = {
        functions: docFunctions,
        loadingStates,
        buttonWithLabel: false as const,
    };

    const renderConditionalSlots = (cells: ReactNode[]) => {
        conditionalCedenteSlots.forEach((slot) => {
            const documentData = findDocForSlot(esteiraDocsCedente, slot);
            const docType = slotToDocType(slot);
            const loadingKey = slotLoadingKey(slot);
            cells.push(
                <DocumentsBentoGridCell key={slot.id}>
                    <DocumentsBentoDocCard
                        idEsteira={esteiraId as number}
                        title={slot.label}
                        subtitle={brokerSlotSubtitle(slot)}
                        loadingKey={loadingKey}
                        exigenciaDocumentalId={slot.exigenciaDocumentalId}
                        docInfo={{
                            docContentType: documentData?.content_type ?? '',
                            docDownloadUrl: documentData?.download_url ?? '',
                            docStatus: documentData?.status ?? '',
                            docType,
                            name: slot.label,
                            id: documentData?.id ?? 0,
                            analise: documentData?.analise,
                            docStreamUrl: documentData?.stream_url,
                        }}
                        {...cardProps}
                    />
                </DocumentsBentoGridCell>,
            );
        });
    };

    if (cedenteType === 'PJ') {
        const cells: ReactNode[] = [];
        const contratoSocialDoc = findDocumentByType(esteiraDocsCedente || [], 'CONTRATO_SOCIAL');

        cells.push(
            <DocumentsBentoGridCell key="CONTRATO_SOCIAL">
                <DocumentsBentoDocCard
                    idEsteira={esteiraId as number}
                    title="Contrato Social"
                    docInfo={{
                        docContentType: contratoSocialDoc?.content_type ?? '',
                        docDownloadUrl: contratoSocialDoc?.download_url ?? '',
                        docStatus: contratoSocialDoc?.status ?? '',
                        docType: 'CONTRATO_SOCIAL' as docTypes,
                        name: 'Contrato Social',
                        id: contratoSocialDoc?.id ?? 0,
                        analise: contratoSocialDoc?.analise,
                        docStreamUrl: contratoSocialDoc?.stream_url,
                    }}
                    {...cardProps}
                />
            </DocumentsBentoGridCell>,
        );

        const oficioDocDef = filteredPfDocs.find((doc) => doc.type === OFICIO_REQUISITORIO_DOC_TYPE);
        if (oficioDocDef) {
            const oficioDoc = findDocumentByType(
                esteiraDocsCedente || [],
                OFICIO_REQUISITORIO_DOC_TYPE,
            );
            cells.push(
                <DocumentsBentoGridCell key={OFICIO_REQUISITORIO_DOC_TYPE}>
                    <DocumentsBentoDocCard
                        idEsteira={esteiraId as number}
                        title={oficioDocDef.name}
                        docInfo={{
                            docContentType: oficioDoc?.content_type ?? '',
                            docDownloadUrl: oficioDoc?.download_url ?? '',
                            docStatus: oficioDoc?.status ?? '',
                            docType: OFICIO_REQUISITORIO_DOC_TYPE as docTypes,
                            name: oficioDocDef.name,
                            id: oficioDoc?.id ?? 0,
                            analise: oficioDoc?.analise,
                            docStreamUrl: oficioDoc?.stream_url,
                        }}
                        {...cardProps}
                    />
                </DocumentsBentoGridCell>,
            );
        }

        if (!cedenteData?.representante_legal) {
            cells.push(
                <DocumentsBentoGridCell key="no-representante">
                    <DocumentsBentoPlaceholder
                        alt="Sem representante legal"
                        message="Não há representante legal vinculado ao cedente."
                    />
                </DocumentsBentoGridCell>,
            );
        } else if (!hasActiveEsteiraRepresentante) {
            const representanteData = cedenteData.representante_legal;
            cells.push(
                <DocumentsBentoGridCell key="no-esteira-representante">
                    <DocumentsBentoPlaceholder
                        alt="Sem esteira do representante"
                        message="O representante legal não possui esteira cadastrada."

