'use client';

import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetOverlay } from '@/components/ui/sheet';
import {
    OBSERVACOES_BALLOON_HEADER_CLASS,
    OBSERVACOES_BALLOON_HEADER_STYLE,
    OBSERVACOES_BALLOON_ICON_SHELL_STYLE,
    OBSERVACOES_BALLOON_SHELL_STYLE,
} from '@/constants/due-diligence';
import { COLORS, TYPOGRAPHY, withAlpha } from '@/design-system';
import { cn } from '@/lib/utils';
import { History, X } from 'lucide-react';
import { useMemo } from 'react';
import { useReducedMotion } from 'motion/react';
import { useViewModelPendenciasHistoricoSheet } from '../../ViewModels/PendenciasHistorico/useViewModelPendenciasHistoricoSheet';
import { resolvePendenciasHistoricoSheetWidth } from '../../utils/pendenciasHistoricoSheet';
import { HistoricoDetailPanel, HistoricoDocumentPreviewPanel } from './HistoricoDetailPanel';
import { HistoricoListPanel } from './HistoricoListPanel';

function PendenciasHistoricoSheetInnerView() {
    const viewModel = useViewModelPendenciasHistoricoSheet();
    const { ui, handlers } = viewModel;
    const shouldReduceMotion = useReducedMotion();

    const sheetWidth = useMemo(
        () => resolvePendenciasHistoricoSheetWidth(ui.sheetLevel),
        [ui.sheetLevel],
    );

    return (
        <Sheet open={ui.isOpen} onOpenChange={(open) => !open && handlers.handleClose()}>
            <SheetOverlay
                className="bg-transparent data-[state=closed]:duration-300 data-[state=open]:duration-300"
                style={{ background: withAlpha(COLORS.bg, 0.55) }}
            />
            <SheetContent
                side="right"
                className={cn(
                    'flex h-full max-w-[min(96vw,1280px)] flex-col gap-0 overflow-hidden border p-0 shadow-celer-overlay',
                    '[&>button.absolute]:hidden',
                    !shouldReduceMotion && 'transition-[width] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]',
                )}
                style={{
                    ...OBSERVACOES_BALLOON_SHELL_STYLE,
                    width: sheetWidth,
                    boxShadow: 'var(--shadow-overlay)',
                }}
            >
                <div className="flex h-full w-full min-w-0 flex-col">
                    <div className={OBSERVACOES_BALLOON_HEADER_CLASS} style={OBSERVACOES_BALLOON_HEADER_STYLE}>
                        <span
                            className="flex size-8 shrink-0 items-center justify-center rounded-lg"
                            style={OBSERVACOES_BALLOON_ICON_SHELL_STYLE}
                            aria-hidden
                        >
                            <History size={16} />
                        </span>
                        <div className="min-w-0 flex-1">
                            <div className={cn(TYPOGRAPHY.title, 'leading-tight text-foreground')}>
                                Histórico de pendências
                            </div>
                            <p className={cn(TYPOGRAPHY.hint, 'mt-0.5 truncate text-muted-foreground')}>
                                Pendências resolvidas deste ativo
                                {ui.pendenciasResolvidas.length > 0
                                    ? ` · ${ui.pendenciasResolvidas.length}`
                                    : ''}
                            </p>
                        </div>
                        <Button
                            type="button"
                            onClick={handlers.handleClose}
                            variant="ghost"
                            size="icon"
                            aria-label="Fechar histórico de pendências"
                            className="size-8 shrink-0 text-muted-foreground hover:text-foreground"
                        >
                            <X size={16} aria-hidden />
                        </Button>
                    </div>

export function HistoricoDocumentPreviewPanel({
    nome,
    url,
    documentType,
    onClose,
}: IHistoricoDocumentPreviewPanelProps) {
    const resolvedType = documentType || (isPdfFileName(nome) ? 'pdf' : 'img');

    return (
        <div className="flex h-full min-h-0 flex-col border-l border-celer-line">
            <div className="flex shrink-0 items-center justify-between gap-3 border-b border-celer-line px-4 py-3">
                <div className="min-w-0">
                    <p className="m-0 truncate font-satoshi text-sm font-semibold text-foreground">
                        {nome}
                    </p>
                    <p className="m-0 text-[0.7rem] text-muted-foreground">Preview do documento</p>
                </div>
                <button
                    type="button"
                    onClick={onClose}
                    aria-label="Fechar preview do documento"
                    className="flex size-8 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-black/5 hover:text-foreground dark:hover:bg-white/5"
                >
                    <X size={16} aria-hidden />
                </button>
            </div>
            <div className="min-h-0 flex-1 overflow-auto bg-celer-panel/30 p-3">
                <DocumentPreviewer url={url} documentType={resolvedType} pageWidth={70} />
            </div>
        </div>
    );
}

