return (
    <div
        className={cn(
            'flex w-full items-center gap-3 rounded-xl border px-3 py-3',
            isRejected
                ? 'border-amber-300 bg-amber-50 dark:border-amber-500/40 dark:bg-amber-950/40'
                : isApproved
                  ? 'border-emerald-200 bg-emerald-50 dark:border-emerald-900 dark:bg-emerald-950/40'
                  : 'border-celer-line bg-celer-paper hover:border-celer-blue/40',
        )}
    >
        {attached && downloadUrl ? (
            <button
                type="button"
                onClick={handleOpenPreview}
                title="Visualizar documento"
                className={cn(
                    'relative h-16 w-14 shrink-0 overflow-hidden rounded-[9px] border bg-celer-panel',
                    isRejected
                        ? 'border-amber-300 dark:border-amber-500/40'
                        : isApproved
                          ? 'border-emerald-200 dark:border-emerald-900'
                          : 'border-celer-line hover:border-celer-blue/40',
                )}
            >
                <span className="pointer-events-none absolute inset-0 flex items-start justify-center [&_p]:hidden">
                    <DocumentPreviewer
                        url={downloadUrl}
                        documentType={isPdf ? 'pdf' : 'img'}
                        pageWidth={PREVIEW_THUMB_WIDTH_PX}
                        documentId={item.document?.id}
                    />
                </span>
                <span
                    className={cn(
                        'absolute bottom-1 right-1 grid size-4 place-items-center rounded-full text-white shadow',
                        isRejected
                            ? 'bg-amber-500'
                            : isApproved
                              ? 'bg-emerald-500'
                              : 'bg-celer-blue',
                    )}
                    aria-hidden
                >
                    <Icone className={cn('size-2.5', isBusy && 'animate-spin')} />
                </span>
            </button>
        ) : (
            <span
                className={cn(
                    'grid size-[30px] shrink-0 place-items-center rounded-[9px] text-white',
                    isRejected
                        ? 'bg-amber-500 shadow-[inset_0_1px_0_rgba(255,255,255,0.35),0_1px_2px_rgba(217,119,6,0.4)]'
                        : isApproved
                          ? 'bg-emerald-500 shadow-[inset_0_1px_0_rgba(255,255,255,0.35),0_1px_2px_rgba(5,150,105,0.4)]'
                          : attached
                            ? 'bg-celer-blue shadow-[inset_0_1px_0_rgba(255,255,255,0.35),0_1px_2px_rgba(28,100,242,0.4)]'
                            : 'bg-celer-panel text-celer-muted shadow-[inset_0_1px_2px_rgba(15,23,42,0.12),inset_0_-1px_0_rgba(255,255,255,0.5)] dark:shadow-[inset_0_1px_2px_rgba(0,0,0,0.35)]',
                )}
                aria-hidden
            >
                <Icone className={cn('size-3.5', isBusy && 'animate-spin')} />
            </span>
        )}

        {attached && !isRejected ? (
            <button
                type="button"
                onClick={handleOpenPreview}
                className="min-w-0 flex-1 text-left"
            >
                <span className="text-celer-strong block text-[13px] font-semibold">{item.label}</span>
                <span className="text-celer-muted mt-0.5 block truncate text-[11px]">{subtitle}</span>
            </button>
        ) : (
            <label htmlFor={inputId} className="min-w-0 flex-1 cursor-pointer text-left">
                <span
                    className={cn(
                        'block text-[13px] font-semibold',
                        isRejected ? 'text-amber-800 dark:text-amber-200' : 'text-celer-strong',
                    )}
                >
                    {item.label}
                </span>
                <span
                    className={cn(
                        'mt-0.5 block truncate text-[11px]',
                        isRejected ? 'text-amber-700 dark:text-amber-300' : 'text-celer-muted',
                    )}
                >
                    {subtitle}
                </span>
            </label>
        )}

        {isRejected ? (
            <span className="shrink-0 rounded-md border border-amber-300 bg-celer-paper px-2 py-1 text-[10px] font-extrabold text-amber-800 dark:border-amber-500/40 dark:text-amber-200">
                REENVIAR
            </span>
        ) : null}

        <label
            htmlFor={inputId}
            className={cn(
                'shrink-0 cursor-pointer text-right text-[11px] font-semibold leading-tight',
                isRejected
                    ? 'text-amber-700 dark:text-amber-300'
                    : isApproved
                      ? 'text-emerald-600 dark:text-emerald-400'
                      : attached
                        ? 'max-w-24 text-amber-600 dark:text-amber-400'
                        : 'text-celer-blue',
                isBusy && 'pointer-events-none opacity-60',
            )}
        >
            {ctaLabel}
        </label>

        {attached ? (
            canApproveDocument ? (
                <button
                    type="button"
                    title="Análise IA"
                    disabled={isAiProcessing}
                    onClick={() => setIsAiOpen(true)}
                    className="text-celer-muted hover:text-celer-blue grid size-8 shrink-0 place-items-center rounded-lg"
                >
                    {isAiProcessing ? (
                        <LoaderCircle className="size-3.5 animate-spin" />
                    ) : (
                        <Sparkles className="size-3.5" />
                    )}
                </button>
            ) : (
                <button
                    type="button"
                    title="Baixar"
                    onClick={handleDownload}
                    className="text-celer-muted hover:text-celer-blue grid size-8 shrink-0 place-items-center rounded-lg"
                >
                    <Download className="size-3.5" />
                </button>
            )
        ) : null}

