export function AnaliseRessalvasIntegraModalView({
    ui,
    handlers,
}: IAnaliseRessalvasIntegraModalViewProps) {
    return (
        <div className="grid min-h-0 flex-1 grid-cols-1 overflow-hidden lg:grid-cols-[280px_minmax(0,1fr)_minmax(320px,0.9fr)]">
            <aside className="min-h-0 overflow-y-auto bg-boxdark-2 p-4 diligence-filter-tabs-scroll">
                <label className="relative block">
                    <Search
                        className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-celer-muted"
                        aria-hidden
                    />
                    <input
                        value={ui.searchQuery}
                        onChange={(event) => handlers.onSearchChange(event.target.value)}
                        placeholder="Buscar ressalva..."
                        className="h-11 w-full rounded-xl border border-celer-line bg-white pl-9 pr-3 font-satoshi text-sm text-celer-strong outline-none transition-colors placeholder:text-celer-muted focus:border-celer-blue dark:bg-boxdark dark:text-foreground"
                        aria-label="Buscar ressalva"
                    />
                </label>

                <div className="mt-3 space-y-2" data-testid="analise-ressalvas-list">
                    {ui.ressalvas.length > 0 ? (
                        ui.ressalvas.map((item) => (
                            <AnaliseRessalvaSidebarItem
                                key={item.id}
                                item={item}
                                isSelected={item.id === ui.selectedRessalva?.id}
                                onSelect={() => handlers.onSelectRessalva(item.id)}
                            />
                        ))
                    ) : (
                        <p className={cn('px-2 py-6 text-center text-sm', integraMutedTextClass())}>
                            Nenhuma ressalva encontrada.
                        </p>
                    )}
                </div>
            </aside>

            <section className="min-h-0 overflow-y-auto px-8 py-7 diligence-filter-tabs-scroll">
                {ui.selectedRessalva ? (
                    <div className="space-y-7">
                        <div className="space-y-2">
                            <p className={integraLabelCapsClass()}>Categoria</p>
                            <h3 className="font-satoshi text-lg font-bold uppercase tracking-[-0.01em] text-celer-strong dark:text-foreground">
                                {ui.selectedRessalva.categoryLabel}
                            </h3>
                        </div>

                        <div className="space-y-2">
                            <p className={integraLabelCapsClass()}>Descrição</p>
                            <p className="m-0 whitespace-pre-wrap font-satoshi text-sm leading-7 text-celer-strong dark:text-foreground">
                                {ui.selectedRessalva.descriptionPreview}
                            </p>
                        </div>

                        <div className="space-y-3">
                            <p className={integraLabelCapsClass()}>Documentos da ressalva</p>
                            {ui.selectedRessalvaDocumentSlots.length > 0 ? (
                                <div className="space-y-2">
                                    {ui.selectedRessalvaDocumentSlots.map((slot) => (
                                        <AnaliseRessalvaDocumentSlot
                                            key={slot.slotKey}
                                            slot={slot}
                                            onSelect={() => handlers.onSelectDocument(slot.slotKey)}
                                        />
                                    ))}
                                </div>
                            ) : (
                                <p className={cn('pl-4 text-sm', integraMutedTextClass())}>
                                    Nenhum documento anexado
                                </p>
                            )}
                        </div>
                    </div>
                ) : (
                    <p className={cn('py-10 text-center text-sm', integraMutedTextClass())}>
                        Nenhuma ressalva disponível.
                    </p>
                )}
            </section>

            <section
                className="flex min-h-0 flex-col border-t border-celer-line bg-white p-4 dark:bg-boxdark lg:border-l lg:border-t-0"
                aria-label="Pré-visualização do documento da ressalva"
                data-testid="analise-ressalvas-preview"
            >
                <p className="mb-3 font-satoshi text-xs font-semibold text-celer-strong dark:text-foreground">
                    Preview do documento
                </p>
                <div className="flex min-h-[260px] flex-1 items-center justify-center overflow-hidden">
                    {ui.selectedPreview ? (
                        <DocumentPreviewer
                            url={ui.selectedPreview.url}
                            documentType={ui.selectedPreview.documentType}
                            documentId={ui.selectedPreview.documentId}
                            pageWidth={PREVIEW_PAGE_WIDTH}
                        />
                    ) : (
                        <AnaliseRessalvaPreviewPlaceholder />
                    )}
                </div>
            </section>
        </div>
    );
}

