import { useQuery } from '@tanstack/react-query';
import { FileX, Loader } from 'lucide-react';
import Image from 'next/image';
import { useCallback } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';

// Worker config
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

export function DocumentPreviewer({ url, documentType }: { url: string; documentType: string }) {
    const fetchDocUrl = useCallback(async () => {
        if (documentType === 'pdf') {
            return url;
        }

        try {
            const res = await fetch(url);
            const blob = await res.blob();
            const imageUrl = URL.createObjectURL(blob);
            return imageUrl;
        } catch {
            console.error('Error fetching document URL');
            return null;
        }
    }, [url, documentType]);

    const {
        data: previewUrl,
        isLoading,
        isError,
    } = useQuery({
        queryKey: ['preview-url', documentType, url],
        queryFn: fetchDocUrl,
        enabled: !!url && !!documentType,
    });

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center gap-1">
                <Loader className="animate-spin" size={12} />
                <p className="text-center text-[0.45rem] text-paragraph">Carregando...</p>
            </div>
        );
    }

    if (isError) {
        return (
            <div className="flex flex-col items-center justify-center gap-1">
                <FileX size={20} className="text-gray-300 dark:text-slate-500" />
            </div>

